#[test]
fn work_memory_lifecycle_and_ttl_classification_is_explicit() {
    for status in [
        "complete",
        "completed",
        "completed_pushed",
        "resolved (#119)",
        "done.",
        "closed",
        "finished",
        "superseded",
    ] {
        assert!(work_memory_status_is_terminal(status), "{status}");
    }
    for status in ["active", "WAIT_VALUE_GATE", "blocked_owner", "paused"] {
        assert!(!work_memory_status_is_terminal(status), "{status}");
    }

    let content = "# Finished lane\nstatus: completed_pushed\n";
    assert_eq!(
        work_memory_declared_status(&json!({"content": content}), content),
        "completed_pushed"
    );

    let now = unix_now_secs();
    let expired = MemoryRecord {
        key: "expired-work-memory".to_string(),
        kind: WORK_MEMORY_KIND.to_string(),
        content: "status: active".to_string(),
        tags: vec!["ttl:14d".to_string()],
        related_keys: vec![],
        scope: Some("project:/tmp/work-memory-expired".to_string()),
        created_at: now - 15 * WORK_MEMORY_SECONDS_PER_DAY,
        updated_at: now - 15 * WORK_MEMORY_SECONDS_PER_DAY,
        last_accessed_at: now,
        access_count: 0,
        importance: 0.5,
        status: "active".to_string(),
        trigger_pattern: None,
        superseded_by: None,
    };
    assert!(!work_memory_is_live(&expired, now));
}

#[test]
fn record_ttl_is_live_suppresses_expired_rollback_map_audit_rows() {
    let now = unix_now_secs();
    let mk = |key: &str, tags: Vec<String>, age_days: i64| MemoryRecord {
        key: key.to_string(),
        kind: "observation".to_string(),
        content: "outcome_valence_importance_apply rollback map (3 rows)".to_string(),
        tags,
        related_keys: vec![],
        scope: Some(format!("valence-audit:{key}")),
        created_at: now - age_days * WORK_MEMORY_SECONDS_PER_DAY,
        updated_at: now - age_days * WORK_MEMORY_SECONDS_PER_DAY,
        last_accessed_at: now,
        access_count: 0,
        importance: 0.5,
        status: "active".to_string(),
        trigger_pattern: None,
        superseded_by: None,
    };

    // Past its 14d window → suppressed from retrieval.
    let expired = mk(
        "expired",
        vec!["rollback_map".to_string(), "ttl:14d".to_string()],
        15,
    );
    assert!(!record_ttl_is_live(&expired, now));

    // Within its window → still live (rollback correctness during the window).
    let fresh = mk(
        "fresh",
        vec!["rollback_map".to_string(), "ttl:14d".to_string()],
        3,
    );
    assert!(record_ttl_is_live(&fresh, now));

    // No ttl tag → never affected (byte-identical to prior behavior).
    let untagged = mk("untagged", vec!["rollback_map".to_string()], 400);
    assert!(record_ttl_is_live(&untagged, now));
}

#[test]
fn work_memory_list_fan_in_surfaces_alias_compatible_cross_node_lanes() {
    let mk = |key: &str, scope: &str, accessed: i64| MemoryRecord {
        key: key.to_string(),
        kind: WORK_MEMORY_KIND.to_string(),
        content: format!("content {key}"),
        tags: vec![],
        related_keys: vec![],
        scope: Some(scope.to_string()),
        created_at: 0,
        updated_at: 0,
        last_accessed_at: accessed,
        access_count: 0,
        importance: 0.5,
        status: "active".to_string(),
        trigger_pattern: None,
        superseded_by: None,
    };
    let aliases = "project-id:git:gitlab.com/pallasting/agent-bridge=\
            project:/Users/pallasting/Projects/agent-bridge,\
            project:/Data/CascadeProjects/agent-bridge";
    let requested = "project:/Users/pallasting/Projects/agent-bridge";

    // same_node = the Mac lane already returned by the exact-scope query.
    let same_node = vec![mk(
        "wm_mac",
        "project:/Users/pallasting/Projects/agent-bridge",
        100,
    )];
    // broad = every work_memory row: the Mac lane (dup), an alias-compatible
    // aio2 lane, and an unrelated project's lane that must NOT leak.
    let broad = vec![
        mk(
            "wm_mac",
            "project:/Users/pallasting/Projects/agent-bridge",
            100,
        ),
        mk("wm_aio2", "project:/Data/CascadeProjects/agent-bridge", 200),
        mk(
            "wm_other",
            "project:/Data/CascadeProjects/biocortex-rs",
            300,
        ),
    ];
    let out = merge_alias_compatible_work_memory(same_node, broad, requested, aliases, 8);
    let keys: Vec<&str> = out.iter().map(|r| r.key.as_str()).collect();
    assert!(keys.contains(&"wm_mac"), "same-node lane kept");
    assert!(
        keys.contains(&"wm_aio2"),
        "alias-compatible cross-node lane surfaced"
    );
    assert!(
        !keys.contains(&"wm_other"),
        "unrelated project must NOT leak"
    );
    assert_eq!(out.len(), 2, "exactly mac + aio2, deduped");
    // same-node lane is PINNED first, then cross-node fills the remaining budget.
    assert_eq!(out[0].key, "wm_mac");
    assert_eq!(out[1].key, "wm_aio2");
}

#[test]
fn work_memory_fan_in_pins_same_node_lane_against_eviction() {
    let mk = |key: &str, scope: &str, accessed: i64| MemoryRecord {
        key: key.to_string(),
        kind: WORK_MEMORY_KIND.to_string(),
        content: String::new(),
        tags: vec![],
        related_keys: vec![],
        scope: Some(scope.to_string()),
        created_at: 0,
        updated_at: 0,
        last_accessed_at: accessed,
        access_count: 0,
        importance: 0.5,
        status: "active".to_string(),
        trigger_pattern: None,
        superseded_by: None,
    };
    let aliases = "project-id:git:gitlab.com/pallasting/agent-bridge=\
            project:/Users/pallasting/Projects/agent-bridge,\
            project:/Data/CascadeProjects/agent-bridge";
    let requested = "project:/Users/pallasting/Projects/agent-bridge";
    // One STALE same-node lane + two NEWER cross-node lanes, limit=2. A naive
    // merge-then-truncate would evict the agent's own lane entirely.
    let same_node = vec![mk(
        "wm_mine",
        "project:/Users/pallasting/Projects/agent-bridge",
        10,
    )];
    let broad = vec![
        mk(
            "wm_mine",
            "project:/Users/pallasting/Projects/agent-bridge",
            10,
        ),
        mk(
            "wm_aio2_a",
            "project:/Data/CascadeProjects/agent-bridge",
            200,
        ),
        mk(
            "wm_aio2_b",
            "project:/Data/CascadeProjects/agent-bridge",
            300,
        ),
    ];
    let out = merge_alias_compatible_work_memory(same_node, broad, requested, aliases, 2);
    let keys: Vec<&str> = out.iter().map(|r| r.key.as_str()).collect();
    assert!(
        keys.contains(&"wm_mine"),
        "an agent's own lane must never be evicted by newer cross-node lanes"
    );
    assert_eq!(out.len(), 2, "capped to limit");
    assert_eq!(out[0].key, "wm_mine", "own lane pinned first");
    // room = 2 - 1 = 1 => only the single most-recent cross-node lane (300).
    assert_eq!(out[1].key, "wm_aio2_b");
}

#[test]
fn work_memory_fan_in_without_covering_alias_keeps_only_same_node() {
    let mk = |key: &str, scope: &str| MemoryRecord {
        key: key.to_string(),
        kind: WORK_MEMORY_KIND.to_string(),
        content: String::new(),
        tags: vec![],
        related_keys: vec![],
        scope: Some(scope.to_string()),
        created_at: 0,
        updated_at: 0,
        last_accessed_at: 0,
        access_count: 0,
        importance: 0.5,
        status: "active".to_string(),
        trigger_pattern: None,
        superseded_by: None,
    };
    // The alias covers a DIFFERENT project, so the aio2 agent-bridge lane is
    // NOT compatible and must stay invisible — proves the alias is the
    // load-bearing gate, not an unconditional cross-scope dump.
    let aliases = "project-id:name:other=project:/x/other,project:/y/other";
    let requested = "project:/Users/pallasting/Projects/agent-bridge";
    let same_node = vec![mk(
        "wm_mac",
        "project:/Users/pallasting/Projects/agent-bridge",
    )];
    let broad = vec![
        mk("wm_mac", "project:/Users/pallasting/Projects/agent-bridge"),
        mk("wm_aio2", "project:/Data/CascadeProjects/agent-bridge"),
    ];
    let out = merge_alias_compatible_work_memory(same_node, broad, requested, aliases, 8);
    let keys: Vec<&str> = out.iter().map(|r| r.key.as_str()).collect();
    assert_eq!(
        keys,
        vec!["wm_mac"],
        "only same-node lane; no cross-node leak without a covering alias"
    );
}

#[test]
fn cross_node_peer_lanes_returns_only_cross_node_changed_since_cursor() {
    let mk = |key: &str, scope: &str, updated: i64| MemoryRecord {
        key: key.to_string(),
        kind: WORK_MEMORY_KIND.to_string(),
        content: format!("content {key}"),
        tags: vec![],
        related_keys: vec![],
        scope: Some(scope.to_string()),
        created_at: 0,
        updated_at: updated,
        last_accessed_at: 0,
        access_count: 0,
        importance: 0.5,
        status: "active".to_string(),
        trigger_pattern: None,
        superseded_by: None,
    };
    let aliases = "project-id:git:gitlab.com/pallasting/agent-bridge=\
            project:/Users/pallasting/Projects/agent-bridge,\
            project:/Data/CascadeProjects/agent-bridge";
    let requested = "project:/Users/pallasting/Projects/agent-bridge";
    let broad = vec![
        // own same-node lane — must be EXCLUDED (it's the agent's own).
        mk(
            "wm_mac",
            "project:/Users/pallasting/Projects/agent-bridge",
            500,
        ),
        // aio2 peer lane updated after the cursor — INCLUDED.
        mk(
            "wm_aio2_new",
            "project:/Data/CascadeProjects/agent-bridge",
            300,
        ),
        // aio2 peer lane updated BEFORE the cursor — EXCLUDED by since_ts.
        mk(
            "wm_aio2_old",
            "project:/Data/CascadeProjects/agent-bridge",
            100,
        ),
        // unrelated project — must NOT leak.
        mk(
            "wm_other",
            "project:/Data/CascadeProjects/biocortex-rs",
            999,
        ),
    ];
    let out = cross_node_peer_lanes(requested, broad, aliases, 200, 8);
    let keys: Vec<&str> = out.iter().map(|r| r.key.as_str()).collect();
    assert_eq!(
        keys,
        vec!["wm_aio2_new"],
        "only the cross-node peer lane changed since the cursor; own lane, \
             stale peer lane, and unrelated project all excluded"
    );
    // next-cursor semantics: the returned lane's updated_at is the max.
    assert_eq!(out[0].updated_at, 300);
}

