#[tokio::test]
async fn work_memory_save_list_get_clear_roundtrip() {
    let (hub, _temp_dir) = mk_test_hub_with_store().await;
    let tool = WorkMemoryTool::new(hub);
    let ctx = ToolContext::default();
    let cwd = "/tmp/agent-bridge-work-memory-test";

    let saved = tool
        .execute(
            json!({
                "op": "save",
                "cwd": cwd,
                "session_id": "sess-1",
                "slot": "active",
                "summary": "Preserve the active implementation state across compaction.",
                "next_step": "Run the targeted tests.",
                "files": ["crates/bridge/src/mcp_tools.rs"],
            }),
            &ctx,
        )
        .await
        .expect("save ok");
    let saved = result_json(&saved);
    assert_eq!(saved["saved"], true);
    let key = saved["key"].as_str().expect("key").to_string();

    let listed = tool
        .execute(
            json!({"op": "list", "cwd": cwd, "compact": true, "limit": 4}),
            &ctx,
        )
        .await
        .expect("list ok");
    let listed = result_json(&listed);
    assert_eq!(listed["rows"].as_array().expect("rows").len(), 1);
    assert!(listed["rows"][0]["snippet"]
        .as_str()
        .expect("snippet")
        .contains("Preserve the active implementation state"));

    let got = tool
        .execute(json!({"op": "get", "key": key}), &ctx)
        .await
        .expect("get ok");
    let got = result_json(&got);
    assert_eq!(got["kind"], WORK_MEMORY_KIND);

    let cleared = tool
        .execute(
            json!({
                "op": "clear",
                "cwd": cwd,
                "session_id": "sess-1",
                "slot": "active",
            }),
            &ctx,
        )
        .await
        .expect("clear ok");
    assert_eq!(result_json(&cleared)["deleted"], true);
}

#[tokio::test]
async fn work_memory_terminal_save_clears_the_addressed_slot() {
    let (hub, _temp_dir) = mk_test_hub_with_store().await;
    let store = hub.store.clone().expect("store");
    let tool = WorkMemoryTool::new(hub);
    let ctx = ToolContext::default();
    let cwd = "/tmp/agent-bridge-work-memory-terminal";
    let session_id = "terminal-session";

    let saved = tool
        .execute(
            json!({
                "op": "save",
                "cwd": cwd,
                "session_id": session_id,
                "summary": "This lane is still active.",
            }),
            &ctx,
        )
        .await
        .expect("save active slot");
    assert_eq!(result_json(&saved)["saved"], true);

    let terminal = tool
        .execute(
            json!({
                "op": "save",
                "cwd": cwd,
                "session_id": session_id,
                "status": "completed_pushed",
                "summary": "The lane has a durable checkpoint.",
            }),
            &ctx,
        )
        .await
        .expect("terminal save clears slot");
    let terminal = result_json(&terminal);
    assert_eq!(terminal["saved"], false);
    assert_eq!(terminal["cleared"], true);
    assert_eq!(terminal["deleted"], true);

    let key = work_memory_key(cwd, Some(session_id), WORK_MEMORY_DEFAULT_SLOT);
    assert!(store.memory_get(&key).await.expect("store get").is_none());
    let listed = tool
        .execute(json!({"op": "list", "cwd": cwd, "compact": true}), &ctx)
        .await
        .expect("list after terminal save");
    assert!(result_json(&listed)["rows"]
        .as_array()
        .expect("rows")
        .is_empty());
}

#[tokio::test]
async fn memory_list_implicit_default_caps_overview_rows() {
    let (hub, _temp_dir) = mk_test_hub_with_store().await;
    let store = hub.store.as_ref().expect("store");
    for i in 0..12 {
        store
            .memory_save(&MemoryRecord {
                key: format!("memory_list_default_{i}"),
                kind: "fact".to_string(),
                content: format!("overview row {i} {}", "x".repeat(200)),
                tags: vec!["payload".to_string(), "overview".to_string()],
                related_keys: vec![format!("related_{i}")],
                scope: Some("project:/tmp/memory-list-default".to_string()),
                created_at: 1_780_000_000 + i,
                updated_at: 1_780_000_000 + i,
                last_accessed_at: 1_780_000_000 + i,
                access_count: 0,
                importance: 0.5,
                status: "active".to_string(),
                trigger_pattern: None,
                superseded_by: None,
            })
            .await
            .expect("save memory");
    }

    let tool = MemoryListTool::new(hub);
    let ctx = ToolContext::default();
    let implicit = tool
        .execute(json!({"kind": "fact", "sort": "newest"}), &ctx)
        .await
        .expect("implicit list");
    let implicit = result_json(&implicit);
    assert_eq!(implicit.as_array().expect("implicit rows").len(), 8);

    let explicit = tool
        .execute(json!({"kind": "fact", "sort": "newest", "limit": 12}), &ctx)
        .await
        .expect("explicit list");
    let explicit = result_json(&explicit);
    assert_eq!(explicit.as_array().expect("explicit rows").len(), 12);
}

/// Rows get DISTINCT scopes: memory_save's write-time contradiction
/// detection supersedes >0.5-overlap rows within the SAME kind+scope, so
/// same-scope near-duplicates never survive to consolidation. Cross-scope
/// duplicates are exactly the population memory_consolidate exists for.
fn mk_consolidate_row(
    key: &str,
    content: &str,
    importance: f64,
    scope: Option<&str>,
) -> MemoryRecord {
    MemoryRecord {
        key: key.to_string(),
        kind: "fact".to_string(),
        content: content.to_string(),
        tags: vec![],
        related_keys: vec![],
        scope: scope.map(|s| s.to_string()),
        created_at: 1_780_000_000,
        updated_at: 1_780_000_000,
        last_accessed_at: 1_780_000_000,
        access_count: 0,
        importance,
        status: "active".to_string(),
        trigger_pattern: None,
        superseded_by: None,
    }
}

#[test]
fn consolidate_merge_uplift_target_math() {
    // Rise scales with the absorbed row's strength.
    assert!((consolidate_merge_uplift_target(0.7, 0.6, 0.15, 0.9) - 0.79).abs() < 1e-9);
    // The cap bounds the rise.
    assert!((consolidate_merge_uplift_target(0.85, 0.9, 0.15, 0.9) - 0.9).abs() < 1e-9);
    // A winner already above the cap is never lowered.
    assert!((consolidate_merge_uplift_target(0.95, 0.9, 0.15, 0.9) - 0.95).abs() < 1e-9);
    // Step 0 is a no-op.
    assert!((consolidate_merge_uplift_target(0.5, 0.8, 0.0, 0.9) - 0.5).abs() < 1e-9);
}

#[tokio::test]
async fn consolidate_merge_uplift_raises_winner_and_archives_loser() {
    let (hub, _temp_dir) = mk_test_hub_with_store().await;
    let store = hub.store.clone().expect("store");
    let content_a = "alpha bravo charlie delta echo foxtrot golf hotel india juliet kilo lima";
    let content_b = "alpha bravo charlie delta echo foxtrot golf hotel india juliet kilo mike";
    store
        .memory_save(&mk_consolidate_row("uplift_winner", content_a, 0.7, None))
        .await
        .expect("save winner");
    store
        .memory_save(&mk_consolidate_row(
            "uplift_loser",
            content_b,
            0.6,
            Some("project:/tmp/uplift-t1"),
        ))
        .await
        .expect("save loser");

    let tool = MemoryConsolidateTool::new(hub);
    let res = tool
        .execute(
            json!({"kind": "fact", "dry_run": false}),
            &ToolContext::default(),
        )
        .await
        .expect("execute ok");
    let res = result_json(&res);
    assert_eq!(res["consolidated"], 1, "one merge expected: {res}");
    assert_eq!(res["pairs"][0]["winner"], "uplift_winner");
    assert_eq!(res["pairs"][0]["archived"], "uplift_loser");
    let uplift = &res["pairs"][0]["winner_uplift"];
    assert!((uplift["before"].as_f64().expect("before") - 0.7).abs() < 1e-6);
    assert!((uplift["after"].as_f64().expect("after") - 0.79).abs() < 1e-6);

    let winner = store
        .memory_get("uplift_winner")
        .await
        .expect("get winner")
        .expect("winner row");
    assert!(
        (winner.importance - 0.79).abs() < 1e-6,
        "uplift must persist, got {}",
        winner.importance
    );
    let loser = store
        .memory_get("uplift_loser")
        .await
        .expect("get loser")
        .expect("loser row");
    assert_eq!(loser.status, "archived");
}

