#[test]
fn memory_related_keys_orphan_reduction_prioritizes_orphan_touching_pairs() {
    let mut first_source = mk_mem("first_source", "decision", "first source content", &[]);
    first_source.related_keys = vec!["first_target".into()];
    let first_target = mk_mem("first_target", "lesson", "first target content", &[]);
    let first_source_neighbor = mk_mem(
        "first_source_neighbor",
        "context",
        "source neighbor content",
        &[],
    );
    let first_target_neighbor = mk_mem(
        "first_target_neighbor",
        "context",
        "target neighbor content",
        &[],
    );

    let mut orphan_source = mk_mem("orphan_source", "decision", "orphan source content", &[]);
    orphan_source.related_keys = vec!["orphan_target".into()];
    let orphan_target = mk_mem("orphan_target", "lesson", "orphan target content", &[]);

    let all = vec![
        first_source,
        first_target,
        first_source_neighbor,
        first_target_neighbor,
        orphan_source,
        orphan_target,
    ];
    let mut edges_by_key = HashMap::new();
    edges_by_key.insert(
        "first_source".to_string(),
        vec![mk_edge("first_source", "first_source_neighbor", "relates")],
    );
    edges_by_key.insert(
        "first_target".to_string(),
        vec![mk_edge("first_target", "first_target_neighbor", "relates")],
    );

    let preserve = memory_related_keys_materialize_plan_from_records_with_scope_filter(
        &all,
        &edges_by_key,
        &[],
        &[],
        true,
        true,
        None,
        MemorySearchScopeMode::LocalOnly,
        MemoryRelatedKeysReviewScopeFilter::Compatible,
        MemoryRelatedKeysSelectionStrategy::PreserveOrder,
        1,
        10,
        10,
        80,
    );
    let orphan_first = memory_related_keys_materialize_plan_from_records_with_scope_filter(
        &all,
        &edges_by_key,
        &[],
        &[],
        true,
        true,
        None,
        MemorySearchScopeMode::LocalOnly,
        MemoryRelatedKeysReviewScopeFilter::Compatible,
        MemoryRelatedKeysSelectionStrategy::OrphanReduction,
        1,
        10,
        10,
        80,
    );

    assert_eq!(preserve.safe_candidate_pairs_before_caps, 2);
    assert_eq!(preserve.selected_edges[0].from_key, "first_source");
    assert_eq!(preserve.selected_edges[0].to_key, "first_target");
    assert_eq!(preserve.projected_orphans_after_selected(), 2);

    assert_eq!(orphan_first.safe_candidate_pairs_before_caps, 2);
    assert_eq!(orphan_first.selected_edges[0].from_key, "orphan_source");
    assert_eq!(orphan_first.selected_edges[0].to_key, "orphan_target");
    assert_eq!(orphan_first.projected_orphans_after_selected(), 0);
}

#[tokio::test]
async fn memory_related_keys_materialize_dry_run_exact_scope_excludes_parent_scope_candidates() {
    let (hub, temp_dir) = mk_test_hub_with_store().await;
    let store = hub.store.as_ref().expect("store").clone();

    let mut exact_source = mk_mem_scoped(
        "exact_source",
        "decision",
        "exact source content with durable detail",
        &[],
        Some("project:/repo/app"),
    );
    exact_source.related_keys = vec!["exact_target".into()];
    let exact_target = mk_mem_scoped(
        "exact_target",
        "lesson",
        "exact target content with durable detail",
        &[],
        Some("project:/repo/app"),
    );
    let mut parent_source = mk_mem_scoped(
        "parent_source",
        "decision",
        "parent source content that overlaps by path only",
        &[],
        Some("project:/repo"),
    );
    parent_source.related_keys = vec!["parent_target".into()];
    let parent_target = mk_mem_scoped(
        "parent_target",
        "lesson",
        "parent target content that overlaps by path only",
        &[],
        Some("project:/repo"),
    );
    for rec in [exact_source, exact_target, parent_source, parent_target] {
        store.memory_save(&rec).await.expect("seed memory");
    }

    let tool = MemoryRelatedKeysMaterializeTool::new(hub);
    let schema = tool.schema();
    assert_eq!(
        schema.input_schema["properties"]["scope_filter"]["enum"],
        json!(["compatible", "exact"])
    );
    assert!(schema.input_schema["properties"]
        .get("reviewed_selected_edge_hash_v1")
        .is_some());
    let out = tool
        .execute(
            json!({
                "dry_run": true,
                "scope": "project:/repo/app",
                "scope_mode": "local_only",
                "scope_filter": "exact",
                "max_records": 100,
                "max_edges": 10,
                "preview_chars": 80
            }),
            &ToolContext::default(),
        )
        .await
        .expect("execute materialize dry-run");
    let payload = result_text_as_json(&out);

    assert_eq!(payload["filters"]["scope_filter"], json!("exact"));
    assert_eq!(payload["selected_edges_count"], json!(1));
    let selected_hash = payload["selected_edge_hash_v1"]
        .as_str()
        .expect("selected_edge_hash_v1");
    assert_eq!(selected_hash.len(), 64);
    assert!(selected_hash
        .chars()
        .all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase()));
    assert_eq!(
        payload["selected_edges"][0]["from_key"],
        json!("exact_source")
    );
    assert_eq!(
        payload["selected_edges"][0]["to_key"],
        json!("exact_target")
    );

    let serialized = serde_json::to_string(&payload).expect("serialize payload");
    assert!(!serialized.contains("parent_source"));
    assert!(!serialized.contains("parent_target"));

    let _ = tokio::fs::remove_dir_all(&temp_dir).await;
}

