#[test]
fn tool_policy_codex_lean_excludes_native_overlap_tools() {
    let p = ToolPolicy::from_values(Some("codex-lean"), None, None, Some("all"));

    assert_eq!(p.label(), "codex-lean");
    assert_eq!(p.profile().label(), "essential");
    assert!(p.includes(Tier::Essential, "memory_search"));
    assert!(p.includes(Tier::Essential, "body_status"));
    assert!(p.includes(Tier::Essential, "body_reflex_advice"));
    assert!(p.includes(Tier::Essential, "body_task_span"));
    assert!(p.includes(Tier::Essential, "body_scheduling_report"));
    assert!(p.includes(Tier::Essential, "event_spine_snapshot"));
    assert!(p.includes(Tier::Essential, "readiness_audit"));
    assert!(p.includes(Tier::Essential, "tool_atlas_snapshot"));
    assert!(p.includes(Tier::Essential, "context_governor_snapshot"));
    assert!(p.includes(Tier::Essential, "skills_recommend"));
    assert!(p.includes(Tier::Essential, "skills_route"));
    assert!(p.includes(Tier::Essential, "skills_feedback"));
    assert!(p.includes(Tier::Essential, "session_bootstrap"));
    assert!(p.includes(Tier::Essential, "work_memory"));
    assert!(p.includes(Tier::Niche, "ide_snapshot"));
    // Minimum collab surface: lean keeps read+post+list-threads + presence_list
    // so a lean Codex can still see + reach the whiteboard.
    assert!(p.includes(Tier::Standard, "forum_post"));
    assert!(p.includes(Tier::Standard, "forum_read"));
    assert!(p.includes(Tier::Standard, "forum_list_threads"));
    assert!(p.includes(Tier::Standard, "agent_presence_list"));
    // Lean stays narrower than essential: no subscribe / status / announce.
    assert!(!p.includes(Tier::Standard, "forum_subscribe"));
    assert!(!p.includes(Tier::Standard, "forum_set_thread_status"));
    assert!(!p.includes(Tier::Standard, "agent_presence_announce"));
    assert!(!p.includes(Tier::Essential, "shell_exec"));
    assert!(!p.includes(Tier::Essential, "codebase_search"));
    assert!(!p.includes(Tier::Essential, "codebase_impact"));
    assert!(!p.includes(Tier::Essential, "worktree_list"));
    assert!(!p.includes(Tier::Niche, "browser_navigate"));
}

#[test]
fn tool_policy_chatgpt_read_is_small_read_only_and_isolated() {
    let policy = ToolPolicy::from_values(Some("chatgpt-read"), None, None, Some("all"));
    assert_eq!(policy.label(), "chatgpt-read");
    assert_eq!(policy.profile().label(), "essential");
    assert!(policy.includes(Tier::Essential, "forum_search"));
    assert!(policy.includes(Tier::Essential, "forum_fetch"));

    let registry = build_registry_with_policy(Hub::builder().build(), policy);
    let descriptors = registry.descriptors();
    let names: Vec<_> = descriptors
        .iter()
        .map(|descriptor| descriptor.schema.name.as_str())
        .collect();
    assert_eq!(
        names,
        vec![
            "capabilities",
            "context_governor_snapshot",
            "fetch",
            "search"
        ]
    );
    for descriptor in &descriptors {
        assert!(!descriptor.title.trim().is_empty());
        let annotations = descriptor.annotations.expect("ChatGPT annotation");
        assert!(annotations.read_only_hint);
        assert!(!annotations.destructive_hint);
        assert!(!annotations.open_world_hint);
    }
    for name in ["search", "fetch"] {
        let descriptor = descriptors
            .iter()
            .find(|descriptor| descriptor.schema.name == name)
            .unwrap();
        assert!(descriptor.output_schema.is_some());
        assert_eq!(
            descriptor.schema.input_schema["properties"]
                .as_object()
                .unwrap()
                .len(),
            1,
            "{name} input must remain exactly compatible with ChatGPT knowledge discovery"
        );
    }

    for existing in [
        "codex-essential",
        "codex-lean",
        "claude-standard",
        "gemini-lean",
    ] {
        let names: Vec<_> = build_registry_with_policy(
            Hub::builder().build(),
            ToolPolicy::from_values(Some(existing), None, None, None),
        )
        .list()
        .into_iter()
        .map(|schema| schema.name)
        .collect();
        assert!(!names.iter().any(|name| name == "search" || name == "fetch"));
    }
}

