#[test]
fn tool_atlas_schema_has_compact_controls_without_polluting_dispatch_audit() {
    let p = ToolPolicy::from_values(Some("codex-lean"), None, None, None);
    let schemas = build_registry_with_policy(Hub::builder().build(), p).list();
    let atlas = schemas
        .iter()
        .find(|s| s.name == "tool_atlas_snapshot")
        .expect("tool_atlas_snapshot schema");
    let audit = schemas
        .iter()
        .find(|s| s.name == "mcp_dispatch_audit")
        .expect("mcp_dispatch_audit schema");

    assert!(atlas.input_schema["properties"].get("limit").is_some());
    assert_eq!(
        atlas.input_schema["properties"]["limit"]["default"],
        json!(8)
    );
    assert!(atlas.input_schema["properties"]
        .get("include_tools")
        .is_some());
    assert!(audit.input_schema["properties"]
        .get("include_tools")
        .is_none());
}

#[test]
fn dispatch_telemetry_accepts_chatgpt_source_without_reclassifying_openai_codex() {
    let p = ToolPolicy::from_values(Some("all-dev"), None, None, None);
    let schemas = build_registry_with_policy(Hub::builder().build(), p).list();

    for tool_name in [
        "mcp_dispatch_audit",
        "tool_atlas_snapshot",
        "gos_lite_snapshot",
    ] {
        let schema = schemas
            .iter()
            .find(|schema| schema.name == tool_name)
            .unwrap_or_else(|| panic!("{tool_name} schema"));
        let sources = schema.input_schema["properties"]["source"]["enum"]
            .as_array()
            .expect("source enum");
        assert!(sources.iter().any(|source| source == "chatgpt"));
    }

    assert_eq!(dispatch_normalize_source("chatgpt-read"), Some("chatgpt"));
    assert_eq!(dispatch_normalize_source("chatgpt-collab"), Some("chatgpt"));
    assert_eq!(dispatch_normalize_source("ChatGPT"), Some("chatgpt"));
    assert_eq!(dispatch_normalize_source("OpenAI Codex"), Some("codex"));
}

