// ── agent_spawn policy → backend mapping ──────────────────────────────

async fn wait_for_claude_output(
    rt: &ab_agent::ClaudeCodeRuntime,
    session: &SessionId,
    needle: &str,
) -> bool {
    for _ in 0..80 {
        if rt
            .read_interactive_output(session)
            .map(|out| out.contains(needle))
            .unwrap_or(false)
        {
            return true;
        }
        tokio::time::sleep(Duration::from_millis(25)).await;
    }
    false
}

