#[tokio::test]
async fn agent_send_input_routes_to_live_session_runtime() {
    use ab_agent::AgentRuntime;

    let (base_hub, temp_dir) = mk_test_hub_with_store().await;
    let store = base_hub.store.as_ref().expect("store").clone();
    let rt =
        Arc::new(ab_agent::ClaudeCodeRuntime::with_binary("/bin/cat").with_store(store.clone()));
    let hub = crate::Hub::builder().store(store).agent(rt.clone()).build();

    let session = rt
        .spawn(SpawnConfig {
            cwd: temp_dir.display().to_string(),
            interactive: true,
            ..Default::default()
        })
        .await
        .expect("spawn interactive cat");

    let out = AgentSendInputTool::new(hub.clone())
        .execute(
            json!({"id": session.id.as_str(), "text": "mcp-follow-up-turn"}),
            &ToolContext::default(),
        )
        .await
        .expect("send_input execute");
    assert!(!out.is_error, "send_input should succeed: {out:?}");
    let payload = result_text_as_json(&out);
    assert_eq!(payload["status"], json!("sent"));
    assert_eq!(payload["id"], json!(session.id.as_str()));
    assert_eq!(payload["runtime_id"], json!("claude-code"));

    assert!(
        wait_for_claude_output(&rt, &session.id, "mcp-follow-up-turn").await,
        "follow-up turn should be written into the live PTY session"
    );

    let listed = AgentSessionListTool::new(hub)
        .execute(
            json!({"state": "running", "limit": 10}),
            &ToolContext::default(),
        )
        .await
        .expect("list execute");
    assert!(!listed.is_error, "session list should succeed: {listed:?}");
    let rows = result_text_as_json(&listed);
    let row = rows
        .as_array()
        .expect("session list array")
        .iter()
        .find(|row| row["id"] == json!(session.id.as_str()))
        .expect("interactive session in running list");
    assert_eq!(row["liveness"], json!("alive"));
    assert!(
        row["pid"].as_u64().is_some(),
        "running row should carry pid"
    );

    rt.kill(&session.id).await.expect("kill interactive cat");
    for _ in 0..40 {
        if rt.interactive_count() == 0 {
            break;
        }
        tokio::time::sleep(Duration::from_millis(25)).await;
    }
    let _ = tokio::fs::remove_dir_all(&temp_dir).await;
}

/// Regression: `agent_kill` must route to the runtime that OWNS the session
/// (by its stored `runtime_id`), not the configured primary. Before the fix
/// the handler always killed via `hub.agent`; a session owned by a
/// non-primary runtime (e.g. gemini while the primary is claude-code) was
/// never found in the primary's process-local interactive map, so kill
/// returned a spurious "no live child" and leaked the live child tree. Here
/// the primary is a mock and the session is owned by a real (cat-backed)
/// runtime registered separately: only owner-routed kill tears the PTY down.
#[tokio::test]
async fn agent_kill_routes_to_session_owning_runtime_not_primary() {
    use ab_agent::AgentRuntime;

    let (base_hub, temp_dir) = mk_test_hub_with_store().await;
    let store = base_hub.store.as_ref().expect("store").clone();
    // The session OWNER: a real interactive runtime (id "claude-code").
    let owner =
        Arc::new(ab_agent::ClaudeCodeRuntime::with_binary("/bin/cat").with_store(store.clone()));
    // The configured PRIMARY is a DIFFERENT runtime — pre-fix, kill went here.
    let hub = crate::Hub::builder()
        .store(store)
        .agent(mock("mock-primary", false))
        .register_agent(owner.clone())
        .build();

    let session = owner
        .spawn(SpawnConfig {
            cwd: temp_dir.display().to_string(),
            interactive: true,
            ..Default::default()
        })
        .await
        .expect("spawn interactive cat");
    assert_eq!(
        owner.interactive_count(),
        1,
        "session should be live before kill"
    );

    let out = AgentKillTool::new(hub)
        .execute(json!({"id": session.id.as_str()}), &ToolContext::default())
        .await
        .expect("kill execute");
    assert!(
        !out.is_error,
        "kill should succeed by routing to the owner: {out:?}"
    );

    // The OWNER's live PTY must actually be torn down, proving the kill
    // reached the owner and not the mock primary.
    let mut killed = false;
    for _ in 0..80 {
        if owner.interactive_count() == 0 {
            killed = true;
            break;
        }
        tokio::time::sleep(Duration::from_millis(25)).await;
    }
    assert!(
        killed,
        "owner's interactive session must be killed — kill routed to the session's runtime"
    );
    let _ = tokio::fs::remove_dir_all(&temp_dir).await;
}

