#[tokio::test]
async fn agent_spawn_interactive_rejects_non_pty_backends_before_spawn() {
    let hub = crate::Hub::builder()
        .register_agent(Arc::new(ab_agent::AuggieRuntime::with_binary(
            "/definitely/not/auggie",
        )))
        .register_agent(Arc::new(ab_agent::OzAgentRuntime::with_binary(
            "/definitely/not/oz",
        )))
        .build();
    let tool = AgentSpawnTool::new(hub);

    for (backend, runtime_id) in [
        ("auggie", "auggie"),
        ("warp-oz", "warp-oz"),
        ("oz", "warp-oz"),
    ] {
        let out = tool
            .execute(
                json!({
                    "cwd": "/tmp",
                    "prompt": "must fail before process spawn",
                    "backend": backend,
                    "interactive": true
                }),
                &ToolContext::default(),
            )
            .await
            .expect("agent_spawn execute");
        assert!(
            out.is_error,
            "{backend} interactive spawn should fail closed"
        );
        let msg = result_text(&out);
        assert!(
            msg.contains(&format!(
                "{runtime_id}: interactive sessions are not supported"
            )),
            "{backend} should reject via runtime interactive gate, got: {msg}"
        );
        assert!(
            !msg.contains("No such file") && !msg.contains("spawn "),
            "{backend} should reject before attempting the missing binary, got: {msg}"
        );
    }
}

// agent_spawn primary-to-backup failover
struct MockRuntime {
    id: String,
    fail: bool,
}

#[async_trait]
impl ab_agent::AgentRuntime for MockRuntime {
    fn id(&self) -> &str {
        &self.id
    }
    async fn spawn(&self, cfg: SpawnConfig) -> ab_core::Result<ab_agent::AgentSession> {
        if self.fail {
            Err(ab_core::Error::Backend(format!(
                "{}: mock spawn fail",
                self.id
            )))
        } else {
            Ok(ab_agent::AgentSession {
                id: ab_core::SessionId::new(),
                runtime_id: self.id.clone(),
                cwd: cfg.cwd,
                sandbox_profile_requested: None,
            })
        }
    }
    async fn send_input(&self, _s: &ab_core::SessionId, _t: &str) -> ab_core::Result<()> {
        Ok(())
    }
    async fn capabilities(&self) -> ab_agent::AgentCapabilities {
        ab_agent::AgentCapabilities::default()
    }
}

fn mock(id: &str, fail: bool) -> Arc<dyn ab_agent::AgentRuntime> {
    Arc::new(MockRuntime {
        id: id.to_string(),
        fail,
    })
}

static AGENT_SPAWN_FALLBACK_ENV_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

struct AgentSpawnFallbackEnvGuard {
    key: &'static str,
    old: Option<std::ffi::OsString>,
}

impl AgentSpawnFallbackEnvGuard {
    fn set(key: &'static str, value: &str) -> Self {
        let old = std::env::var_os(key);
        std::env::set_var(key, value);
        Self { key, old }
    }
}

impl Drop for AgentSpawnFallbackEnvGuard {
    fn drop(&mut self) {
        match &self.old {
            Some(value) => std::env::set_var(self.key, value),
            None => std::env::remove_var(self.key),
        }
    }
}

