#[tokio::test]
async fn agent_spawn_execute_uses_fallback_chain_when_backend_omitted() {
    let _env_lock = AGENT_SPAWN_FALLBACK_ENV_LOCK
        .lock()
        .unwrap_or_else(|e| e.into_inner());
    let _env =
        AgentSpawnFallbackEnvGuard::set("AGENT_BRIDGE_AGENT_FALLBACK_CHAIN", "primary,backup");

    let primary = mock("primary", true);
    let backup = mock("backup", false);
    let hub = crate::Hub::builder()
        .agent(primary)
        .register_agent(backup)
        .build();
    let out = AgentSpawnTool::new(hub)
        .execute(
            json!({"cwd": "/tmp", "prompt": "hello from fallback test"}),
            &ToolContext::default(),
        )
        .await
        .expect("agent_spawn execute");

    assert!(!out.is_error, "fallback spawn should succeed: {out:?}");
    let payload = result_text_as_json(&out);
    assert_eq!(payload["runtime_id"], json!("backup"));
    assert_eq!(payload["cwd"], json!("/tmp"));
    assert_eq!(payload["failover"]["attempted"], json!(["primary"]));
    assert_eq!(payload["failover"]["used"], json!("backup"));
    assert_eq!(
        payload["body_scheduling_advice"]["schema_version"],
        crate::body_telemetry::BODY_SCHEDULING_ADVICE_SCHEMA_V0
    );
    assert_eq!(payload["body_scheduling_advice"]["workload_class"], "heavy");
    assert_eq!(payload["body_scheduling_advice"]["blocked"], false);
    assert_eq!(
        payload["body_scheduling_advice"]["execution_changed"],
        false
    );
    assert_eq!(payload["body_scheduling_event_recorded"], false);
}

fn body_event(action: &str, target: &str, facts: Value) -> ab_store::SemanticEventRecord {
    ab_store::SemanticEventRecord {
        ts: 100,
        actor: "mcp".to_string(),
        source: "body_telemetry".to_string(),
        action: action.to_string(),
        target: Some(target.to_string()),
        verdict_status: "unknown".to_string(),
        verdict_method: "test".to_string(),
        evidence: None,
        facts: facts.to_string(),
        descriptor: None,
    }
}

#[test]
fn body_scheduling_report_pairs_compact_events_without_causal_claims() {
    let advice = body_event(
        "scheduling_advice_observed",
        "span-1",
        json!({
            "schema_version": crate::body_telemetry::BODY_SCHEDULING_ADVICE_SCHEMA_V0,
            "session_id": "opaque-session",
            "runtime_id": "kilo",
            "span_id": "span-1",
            "advice": {
                "pressure": "elevated",
                "workload_class": "heavy",
                "recommendation": "prefer_single_heavy_task",
                "suggested_max_parallelism": 1,
                "blocked": false,
                "execution_changed": false,
                "changes_routing": false,
                "changes_parallelism": false
            }
        }),
    );
    let span = body_event(
        "task_span_closed",
        "span-1",
        json!({
            "schema_version": crate::body_telemetry::TASK_RESOURCE_SPAN_SCHEMA_V0,
            "span_id": "span-1",
            "task_kind": "agent_spawn",
            "state": "closed",
            "before_pressure": "elevated",
            "after_pressure": "nominal"
        }),
    );

    let report = body_scheduling_report_from_events(&[advice, span], 600, 500, true, 200);
    assert_eq!(
        report["schema_version"],
        crate::body_telemetry::BODY_SCHEDULING_REPORT_SCHEMA_V0
    );
    assert_eq!(report["counts"]["paired"], 1);
    assert_eq!(report["counts"]["closed_pairs"], 1);
    assert_eq!(report["counts"]["pressure_aligned_pairs"], 1);
    assert_eq!(report["counts"]["safety_violations"], 0);
    assert_eq!(report["rates"]["paired_coverage"], 1.0);
    assert_eq!(
        report["pressure_transitions"]["observed"]["elevated->nominal"],
        1
    );
    assert_eq!(report["pressure_transitions"]["direction"]["improved"], 1);
    assert_eq!(report["pressure_transitions"]["direction"]["unchanged"], 0);
    assert_eq!(report["pressure_transitions"]["direction"]["worsened"], 0);
    assert_eq!(
        report["pressure_transitions"]["causal_attribution_allowed"],
        false
    );
    assert_eq!(
        report["pressure_transitions"]["recommendation_effectiveness_claimed"],
        false
    );
    assert_eq!(
        report["observation_window"]["status"],
        "within_requested_window"
    );
    assert_eq!(
        report["observation_window"]["first_paired_at_unix_secs"],
        100
    );
    assert_eq!(
        report["observation_window"]["last_paired_at_unix_secs"],
        100
    );
    assert_eq!(report["observation_window"]["newest_paired_age_secs"], 100);
    assert_eq!(report["observation_window"]["observed_span_secs"], 0);
    assert_eq!(
        report["observation_window"]["newest_within_requested_window"],
        true
    );
    assert_eq!(report["observation_window"]["collects_new_samples"], false);
    assert_eq!(report["observation_window"]["changes_execution"], false);
    assert_eq!(report["observation_window"]["policy_change_allowed"], false);
    assert_eq!(
        report["evaluation"]["status"],
        "insufficient_paired_observations"
    );
    assert_eq!(report["evaluation"]["causal_quality_evaluable"], false);
    assert_eq!(report["evaluation"]["policy_change_allowed"], false);
    assert_eq!(report["calibration"]["minimum_paired_observations"], 5);
    assert_eq!(report["calibration"]["minimum_pair_gate_met"], false);
    assert_eq!(
        report["calibration"]["readiness_status"],
        "insufficient_paired_observations"
    );
    assert_eq!(report["calibration"]["causal_quality_evaluable"], false);
    assert_eq!(report["calibration"]["policy_change_allowed"], false);
    assert!(report["calibration"]["coverage"]["pressure"]["missing"]
        .as_array()
        .unwrap()
        .iter()
        .any(|value| value == "critical"));
    assert_eq!(report["rows"][0]["runtime_id"], "kilo");
    assert!(report["rows"][0].get("session_id").is_none());
    assert!(report["rows"][0].get("sample").is_none());
}

