/// Seed the standard 3-row outcome cohort used by the importance-apply
/// tests: +1.0 (rendered_ok+approved), -1.0 (failed+rejected), and one
/// non-derivable bare row. Distinct scope per row (auto-supersede guard).
async fn seed_valence_apply_cohort(store: &std::sync::Arc<dyn ab_store::StateStore>) {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs() as i64;
    let seeds: [(&str, &str, Vec<&str>); 3] = [
        (
            "outcome_ia",
            "outcome:ia",
            vec![
                "verify:rendered_ok",
                "decision:approved",
                "method:browser_eval",
            ],
        ),
        (
            "outcome_ib",
            "outcome:ib",
            vec!["verify:failed", "decision:rejected", "method:browser_eval"],
        ),
        ("outcome_ic", "outcome:ic", vec![]),
    ];
    for (key, scope, tags) in seeds {
        let rec = MemoryRecord {
            key: key.into(),
            kind: "present_outcome".into(),
            content: format!("outcome row {key} distinct alpha beta gamma"),
            tags: tags.into_iter().map(|s| s.to_string()).collect(),
            related_keys: vec![],
            scope: Some(scope.into()),
            created_at: now,
            updated_at: now,
            last_accessed_at: 0,
            access_count: 0,
            importance: 0.5,
            status: "active".into(),
            trigger_pattern: None,
            superseded_by: None,
        };
        store.memory_save(&rec).await.expect("save");
    }
}

#[tokio::test]
async fn outcome_valence_importance_apply_dry_run_writes_nothing() {
    let (hub, temp_dir) = mk_test_hub_with_store().await;
    let store = hub.store.clone().expect("store");
    seed_valence_apply_cohort(&store).await;

    let tool = OutcomeValenceImportanceApplyTool::new(hub);
    let res = tool
        .execute(json!({}), &ToolContext::default())
        .await
        .expect("execute ok");
    assert!(!res.is_error, "dry run must succeed");
    let v = result_json(&res);

    assert_eq!(
        v["schema"],
        "agent_bridge.outcome_valence_importance_apply.v0"
    );
    assert_eq!(v["read_only"], true);
    assert_eq!(v["boundary"]["mutates_ab_memory"], false);
    assert_eq!(v["boundary"]["changes_memory_search_order"], false);
    // +1.0 → 0.9 (ceiling) and -1.0 → 0.1 (floor); both |Δ|=0.4 ≥ min_delta.
    assert_eq!(v["summary"]["present_outcome_rows"], 3);
    assert_eq!(v["summary"]["derivable_rows"], 2);
    assert_eq!(v["summary"]["candidates"], 2);
    assert_eq!(v["summary"]["applied"], 0);
    assert!(v["audit_memory_key"].is_null());

    // Store untouched: every row still at the hardcoded 0.5.
    let rows = store.active_outcome_meta_rows().await.expect("meta rows");
    assert_eq!(rows.len(), 3);
    assert!(rows.iter().all(|r| (r.importance - 0.5).abs() < 1e-9));

    let _ = tokio::fs::remove_dir_all(&temp_dir).await;
}

#[tokio::test]
async fn outcome_valence_importance_apply_confirm_applies_audits_and_is_idempotent() {
    let (hub, temp_dir) = mk_test_hub_with_store().await;
    let store = hub.store.clone().expect("store");
    seed_valence_apply_cohort(&store).await;

    let tool = OutcomeValenceImportanceApplyTool::new(hub);
    let res = tool
        .execute(json!({"confirm_apply": true}), &ToolContext::default())
        .await
        .expect("execute ok");
    assert!(!res.is_error, "apply must succeed");
    let v = result_json(&res);

    assert_eq!(v["read_only"], false);
    assert_eq!(v["boundary"]["mutates_ab_memory"], true);
    assert_eq!(v["boundary"]["changes_memory_search_order"], true);
    assert_eq!(v["summary"]["candidates"], 2);
    assert_eq!(v["summary"]["applied"], 2);
    assert_eq!(v["summary"]["failed"], 0);

    // Importance really moved: +1.0 → ceiling 0.9, -1.0 → floor 0.1, bare → 0.5.
    let rows = store.active_outcome_meta_rows().await.expect("meta rows");
    let by_key: std::collections::HashMap<&str, f64> = rows
        .iter()
        .map(|r| (r.key.as_str(), r.importance))
        .collect();
    assert!((by_key["outcome_ia"] - 0.9).abs() < 1e-9, "ia -> ceiling");
    assert!((by_key["outcome_ib"] - 0.1).abs() < 1e-9, "ib -> floor");
    assert!((by_key["outcome_ic"] - 0.5).abs() < 1e-9, "ic untouched");

    // Rollback map persisted BEFORE the writes, carrying the old values.
    let audit_key = v["audit_memory_key"]
        .as_str()
        .expect("audit key")
        .to_string();
    let audit = store
        .memory_get(&audit_key)
        .await
        .expect("get audit")
        .expect("audit record exists");
    assert!(audit.content.contains("outcome_ia"));
    assert!(audit.content.contains("\"old_importance\": 0.5"));
    assert!(audit.tags.iter().any(|t| t == "rollback_map"));

    // Applied rows carry the durable label + the one-shot stamp.
    let ia = store
        .memory_get("outcome_ia")
        .await
        .expect("get ia")
        .expect("ia exists");
    assert!(ia.tags.contains(&"valence:+1.000".to_string()));
    assert!(ia.tags.contains(&"valence_class:positive".to_string()));
    assert!(ia.tags.contains(&"valence_applied:+1.000".to_string()));

    // Second confirm pass is a no-op: the stamp matches the derived
    // valence, so both rows are skipped one-shot (not merely min_delta).
    let res2 = tool
        .execute(json!({"confirm_apply": true}), &ToolContext::default())
        .await
        .expect("execute ok");
    let v2 = result_json(&res2);
    assert_eq!(v2["summary"]["candidates"], 0);
    assert_eq!(v2["summary"]["skipped_already_stamped"], 2);
    assert_eq!(v2["summary"]["applied"], 0);
    assert!(v2["audit_memory_key"].is_null());

    let _ = tokio::fs::remove_dir_all(&temp_dir).await;
}

#[tokio::test]
async fn stable_sync_roundtrip_receiver_rederives_stripped_stamp() {
    // End-to-end proof of the stamp-strip fix's healing claim: node A
    // applies (importance derived + stamp minted BY THE REAL TOOL, so the
    // bridge's valence_applied_tag constant is exercised against the store
    // export's hardcoded strip prefix — a drift guard for the duplicated
    // literal); the stable export drops the stamp; node B imports the row
    // and its own apply pass RE-derives importance and re-stamps, instead
    // of being pinned at kind-default by a travelled stamp (the pre-fix
    // failure).
    let (hub_a, dir_a) = mk_test_hub_with_store().await;
    let store_a = hub_a.store.clone().expect("store a");
    seed_valence_apply_cohort(&store_a).await;
    OutcomeValenceImportanceApplyTool::new(hub_a)
        .execute(json!({"confirm_apply": true}), &ToolContext::default())
        .await
        .expect("apply on node A");
    let ia = store_a
        .memory_get("outcome_ia")
        .await
        .expect("get ia")
        .expect("ia exists");
    assert!(
        (ia.importance - 0.9).abs() < 1e-9
            && ia.tags.contains(&"valence_applied:+1.000".to_string()),
        "precondition: node A applied + stamped"
    );

    let jsonl = dir_a.join("stable-sync.jsonl");
    store_a
        .memory_export(
            &ab_store::MemoryExportFilter {
                stable_sync_metadata: true,
                ..Default::default()
            },
            &jsonl,
        )
        .await
        .expect("stable export");

    let (hub_b, dir_b) = mk_test_hub_with_store().await;
    let store_b = hub_b.store.clone().expect("store b");
    store_b
        .memory_import(&jsonl, ab_store::ImportConflictPolicy::Skip, None)
        .await
        .expect("import on node B");

    let ia_b = store_b
        .memory_get("outcome_ia")
        .await
        .expect("get ia b")
        .expect("ia imported");
    assert!(
        (ia_b.importance - 0.5).abs() < 1e-9,
        "received row at kind-default importance, got {}",
        ia_b.importance
    );
    assert!(
        !ia_b.tags.iter().any(|t| t.starts_with("valence_applied:")),
        "received row carries no stamp, got {:?}",
        ia_b.tags
    );
    assert!(
        ia_b.tags.contains(&"verify:rendered_ok".to_string()),
        "facet tags travel (they drive derivation)"
    );

    // Node B's own apply pass heals: derives from facets, writes, stamps.
    let res_b = OutcomeValenceImportanceApplyTool::new(hub_b)
        .execute(json!({"confirm_apply": true}), &ToolContext::default())
        .await
        .expect("apply on node B");
    let vb = result_json(&res_b);
    assert!(
        vb["summary"]["applied"].as_u64().unwrap_or(0) >= 1,
        "receiver re-derives instead of skipping: {}",
        vb["summary"]
    );
    let ia_b2 = store_b
        .memory_get("outcome_ia")
        .await
        .expect("get ia b2")
        .expect("ia exists b2");
    assert!(
        (ia_b2.importance - 0.9).abs() < 1e-9,
        "receiver importance re-derived to 0.9, got {}",
        ia_b2.importance
    );
    assert!(
        ia_b2.tags.contains(&"valence_applied:+1.000".to_string()),
        "receiver minted its own stamp"
    );

    let _ = tokio::fs::remove_dir_all(&dir_a).await;
    let _ = tokio::fs::remove_dir_all(&dir_b).await;
}

#[tokio::test]
async fn outcome_valence_importance_apply_rerun_preserves_prior_audit() {
    let (hub, temp_dir) = mk_test_hub_with_store().await;
    let store = hub.store.clone().expect("store");
    seed_valence_apply_cohort(&store).await;

    let tool = OutcomeValenceImportanceApplyTool::new(hub);
    let v1 = result_json(
        &tool
            .execute(json!({"confirm_apply": true}), &ToolContext::default())
            .await
            .expect("pass 1"),
    );
    let audit1 = v1["audit_memory_key"]
        .as_str()
        .expect("audit 1")
        .to_string();

    // Immediate param-change rerun (same unix second is the hazard case):
    // ceiling 0.7 re-targets the 0.9 row; restamp overrides the one-shot
    // stamp pass 1 just minted.
    let v2 = result_json(
        &tool
            .execute(
                json!({"confirm_apply": true, "ceiling": 0.7, "restamp": true}),
                &ToolContext::default(),
            )
            .await
            .expect("pass 2"),
    );
    let audit2 = v2["audit_memory_key"]
        .as_str()
        .expect("audit 2")
        .to_string();

    // Distinct keys — pass 2 must never upsert-replace pass 1's map…
    assert_ne!(audit1, audit2, "audit keys must be unique per pass");
    // …and pass 1's map must survive ACTIVE (distinct scope defeats the
    // same-kind contradiction supersede) still carrying the true pre-image.
    let a1 = store
        .memory_get(&audit1)
        .await
        .expect("get audit 1")
        .expect("audit 1 exists");
    assert_eq!(a1.status, "active", "prior rollback map must stay active");
    assert!(
        a1.content.contains("\"old_importance\": 0.5"),
        "pass-1 map must keep the original pre-image values"
    );

    let _ = tokio::fs::remove_dir_all(&temp_dir).await;
}

