#[tokio::test(flavor = "current_thread")]
async fn memory_save_get_and_search_surface_continuity_metadata() {
    let (hub, temp_dir) = mk_test_hub_with_store().await;
    let save_tool = MemorySaveTool::new(hub.clone());
    let get_tool = MemoryGetTool::new(hub.clone());
    let search_tool = MemorySearchTool::new(hub.clone());

    let save = save_tool
        .execute(
            json!({
                "key": "continuity_metadata_roundtrip",
                "kind": "decision",
                "content": "continuity metadata searchable anchor",
                "tags": ["baseline"],
                "continuity": {
                    "continuity_role": "state",
                    "retrieval_trigger": "when resuming continuity work",
                    "confidence": "verified",
                    "freshness_policy": "project_phase_bound",
                    "actionability": "plan_influence",
                    "blast_radius": "project",
                    "supersedes": ["continuity_metadata_old"]
                }
            }),
            &ToolContext::default(),
        )
        .await
        .expect("save execute");
    assert_eq!(result_text_as_json(&save)["status"], json!("saved"));

    let got = get_tool
        .execute(
            json!({"key": "continuity_metadata_roundtrip"}),
            &ToolContext::default(),
        )
        .await
        .expect("get execute");
    let got_payload = result_text_as_json(&got);
    assert_eq!(
        got_payload["continuity_metadata"]["continuity_role"],
        json!("state")
    );
    assert_eq!(
        got_payload["continuity_metadata"]["retrieval_trigger"],
        json!("when resuming continuity work")
    );
    assert_eq!(
        got_payload["continuity_metadata"]["supersedes"],
        json!(["continuity_metadata_old"])
    );

    let searched = search_tool
        .execute(
            json!({
                "query": "continuity metadata searchable anchor",
                "limit": 5,
                "mode": "fts"
            }),
            &ToolContext::default(),
        )
        .await
        .expect("search execute");
    let search_payload = result_text_as_json(&searched);
    let hit = search_payload
        .as_array()
        .expect("search array")
        .iter()
        .find(|row| row["record"]["key"] == json!("continuity_metadata_roundtrip"))
        .expect("roundtrip hit");
    assert_eq!(
        hit["record"]["continuity_metadata"]["actionability"],
        json!("plan_influence")
    );

    let _ = tokio::fs::remove_dir_all(&temp_dir).await;
}

#[tokio::test(flavor = "current_thread")]
async fn memory_save_scope_identity_trace_reports_canonical_without_changing_scope() {
    let (hub, temp_dir) = mk_test_hub_with_store().await;
    let repo_dir = temp_dir.join("Agent-Bridge");
    tokio::fs::create_dir_all(&repo_dir)
        .await
        .expect("repo dir");
    let init = std::process::Command::new("git")
        .current_dir(&repo_dir)
        .args(["init"])
        .output()
        .expect("git init");
    assert!(
        init.status.success(),
        "git init failed: {}",
        String::from_utf8_lossy(&init.stderr)
    );
    let remote = std::process::Command::new("git")
        .current_dir(&repo_dir)
        .args([
            "remote",
            "add",
            "origin",
            "git@github.com:Pallasting/Agent-Bridge.git",
        ])
        .output()
        .expect("git remote add");
    assert!(
        remote.status.success(),
        "git remote add failed: {}",
        String::from_utf8_lossy(&remote.stderr)
    );

    let legacy_scope = format!("project:{}", repo_dir.display());
    let save = MemorySaveTool::new(hub.clone())
        .execute(
            json!({
                "key": "scope_identity_trace_roundtrip",
                "kind": "decision",
                "content": "scope identity trace should not change stored scope",
                "scope": legacy_scope,
                "scope_identity_trace": true
            }),
            &ToolContext::default(),
        )
        .await
        .expect("save execute");
    let payload = result_text_as_json(&save);
    assert_eq!(payload["status"], json!("saved"));
    assert_eq!(
        payload["scope_identity_trace"]["canonical_scope"],
        json!("project-id:git:github.com/pallasting/agent-bridge")
    );
    assert_eq!(
        payload["scope_identity_trace"]["evidence"],
        json!("git_remote")
    );
    assert_eq!(
        payload["scope_identity_trace"]["stored_scope_changed"],
        json!(false)
    );

    let got = MemoryGetTool::new(hub.clone())
        .execute(
            json!({"key": "scope_identity_trace_roundtrip"}),
            &ToolContext::default(),
        )
        .await
        .expect("get execute");
    let got_payload = result_text_as_json(&got);
    assert_eq!(got_payload["scope"], json!(legacy_scope));

    let _ = tokio::fs::remove_dir_all(&temp_dir).await;
}

