#[tokio::test]
async fn agent_session_reconcile_defers_untracked_sessions_by_default() {
    use ab_core::SessionId;
    use ab_store::StoredSession;

    let (hub, temp_dir) = mk_test_hub_with_store().await;
    let store = hub.store.as_ref().expect("store").clone();
    let session_id = SessionId::from_raw("ses-stale-local".to_string());
    store
        .save_session(&StoredSession {
            id: session_id.clone(),
            runtime_id: "kilo".to_string(),
            cwd: temp_dir.display().to_string(),
            started_at: dispatch_now_secs() - 600,
            ended_at: None,
            exit_code: None,
            stdout: None,
            stderr: None,
            cloud_run_id: None,
            cloud_run_state: None,
            cloud_session_link: None,
            proc_pid: None,
            proc_pgid: None,
            proc_start_ticks: None,
            owner_pid: None,
            owner_start_ticks: None,
        })
        .await
        .expect("seed running session");

    let tool = AgentSessionReconcileTool::new(hub.clone());
    let dry_run = tool
        .execute(
            json!({"stale_after_secs": 300, "dry_run": true, "limit": 10}),
            &ToolContext::default(),
        )
        .await
        .expect("dry-run execute");
    let dry_payload = result_text_as_json(&dry_run);
    assert_eq!(dry_payload["dry_run"], true);
    assert_eq!(dry_payload["candidate_count"], 0);
    assert_eq!(dry_payload["deferred_untracked_count"], 1);
    assert_eq!(dry_payload["skipped_untracked"], 1);
    assert_eq!(dry_payload["finalised_count"], 0);

    let applied = tool
        .execute(
            json!({"stale_after_secs": 300, "dry_run": false, "limit": 10}),
            &ToolContext::default(),
        )
        .await
        .expect("unconfirmed execute");
    assert!(applied.is_error);
    let row = store
        .load_session(&session_id)
        .await
        .expect("load")
        .expect("session");
    assert!(row.ended_at.is_none());
    assert_eq!(row.exit_code, None);

    let applied = tool
        .execute(
            json!({
                "stale_after_secs": 300,
                "dry_run": false,
                "apply_confirmation": "finalise_stale_sessions",
                "limit": 10
            }),
            &ToolContext::default(),
        )
        .await
        .expect("confirmed execute");
    let payload = result_text_as_json(&applied);
    assert_eq!(payload["dry_run"], false);
    assert_eq!(payload["candidate_count"], 0);
    assert_eq!(payload["deferred_untracked_count"], 1);
    assert_eq!(payload["finalised_count"], 0);

    let row = store
        .load_session(&session_id)
        .await
        .expect("load")
        .expect("session");
    assert!(row.ended_at.is_none());
    assert_eq!(row.exit_code, None);

    let untracked_without_extra_confirmation = tool
        .execute(
            json!({
                "stale_after_secs": 300,
                "dry_run": false,
                "apply_confirmation": "finalise_stale_sessions",
                "finalise_untracked": true,
                "limit": 10
            }),
            &ToolContext::default(),
        )
        .await
        .expect("untracked confirmation gate execute");
    assert!(untracked_without_extra_confirmation.is_error);

    let forced = tool
        .execute(
            json!({
                "stale_after_secs": 300,
                "dry_run": false,
                "apply_confirmation": "finalise_stale_sessions",
                "finalise_untracked": true,
                "apply_untracked_confirmation": "finalise_untracked_sessions",
                "limit": 10
            }),
            &ToolContext::default(),
        )
        .await
        .expect("confirmed untracked execute");
    let forced_payload = result_text_as_json(&forced);
    assert_eq!(forced_payload["candidate_count"], 1);
    assert_eq!(forced_payload["deferred_untracked_count"], 0);
    assert_eq!(forced_payload["finalised_count"], 1);

    let row = store
        .load_session(&session_id)
        .await
        .expect("load")
        .expect("session");
    assert!(row.ended_at.is_some());
    assert_eq!(row.exit_code, Some(-15));
    assert!(row
        .stderr
        .as_deref()
        .unwrap_or_default()
        .contains("agent_session_reconcile"));
    let _ = tokio::fs::remove_dir_all(&temp_dir).await;
}

