fn mk_cached(key: &str, kind: &str, emb: Vec<f32>) -> (MemoryRecord, Vec<f32>) {
    mk_cached_with_status(key, kind, emb, "active")
}

fn mk_cached_with_status(
    key: &str,
    kind: &str,
    emb: Vec<f32>,
    status: &str,
) -> (MemoryRecord, Vec<f32>) {
    (
        MemoryRecord {
            key: key.to_string(),
            kind: kind.to_string(),
            content: format!("body of {key}"),
            tags: vec![],
            related_keys: vec![],
            scope: None,
            created_at: 0,
            updated_at: 0,
            last_accessed_at: 0,
            access_count: 0,
            importance: 0.5,
            status: status.into(),
            trigger_pattern: None,
            superseded_by: None,
        },
        emb,
    )
}

#[test]
fn p4_pick_evolution_neighbors_skips_self_and_skill_and_below_threshold() {
    // Self: same key, perfect cosine — must be excluded.
    // Skill: passes threshold, must be excluded.
    // Below threshold: cosine ≈ 0.5, must be excluded.
    // Above threshold + non-skill + different key: must appear, sorted desc.
    let new = vec![1.0_f32, 0.0, 0.0];
    let cache = vec![
        mk_cached("self_dup", "lesson", vec![1.0, 0.0, 0.0]), // self by key
        mk_cached("hot_kin", "lesson", vec![0.95, 0.31, 0.0]),
        mk_cached("warm_kin", "decision", vec![0.80, 0.60, 0.0]),
        mk_cached("cool_kin", "context", vec![0.50, 0.87, 0.0]),
        mk_cached("skill_match", "skill", vec![0.99, 0.14, 0.0]),
    ];
    let picks = pick_evolution_neighbors(&cache, "self_dup", &new, 0.65, 5);
    let keys: Vec<&str> = picks.iter().map(|(rec, _)| rec.key.as_str()).collect();

    assert!(!keys.contains(&"self_dup"), "must exclude self by key");
    assert!(!keys.contains(&"skill_match"), "must exclude kind=skill");
    assert!(!keys.contains(&"cool_kin"), "must exclude below-threshold");
    assert_eq!(keys, vec!["hot_kin", "warm_kin"], "sorted desc by cosine");

    // Top-K cap: even if many would qualify, only k returned.
    let picks_top1 = pick_evolution_neighbors(&cache, "self_dup", &new, 0.65, 1);
    assert_eq!(picks_top1.len(), 1);
    assert_eq!(picks_top1[0].0.key, "hot_kin");
}

#[test]
fn p4_pick_evolution_neighbors_in_scope_filters_before_ranking() {
    let scoped_cached = |key: &str, embedding: Vec<f32>, scope: Option<&str>| {
        let mut row = mk_cached(key, "lesson", embedding);
        row.0.scope = scope.map(str::to_string);
        row
    };
    let new = vec![1.0_f32, 0.0, 0.0];
    let cache = vec![
        // The foreign row is the strongest geometric match. Scope filtering
        // must happen before top-k so it cannot crowd out visible candidates.
        scoped_cached(
            "foreign_perfect",
            vec![1.0, 0.0, 0.0],
            Some("project:/tmp/evolve-beta"),
        ),
        scoped_cached(
            "local_visible",
            vec![0.98, 0.20, 0.0],
            Some("project:/tmp/evolve-alpha"),
        ),
        scoped_cached("global_visible", vec![0.90, 0.44, 0.0], None),
    ];

    let local_picks = pick_evolution_neighbors_in_scope(
        &cache,
        "project:/tmp/evolve-alpha",
        "new_local",
        &new,
        0.65,
        2,
    );
    let local_keys: Vec<&str> = local_picks
        .iter()
        .map(|(record, _)| record.key.as_str())
        .collect();
    assert_eq!(
        local_keys,
        vec!["local_visible", "global_visible"],
        "same-project and global neighbors remain after foreign candidates are removed"
    );

    let global_picks =
        pick_evolution_neighbors_in_scope(&cache, "global", "new_global", &new, 0.65, 5);
    let global_keys: Vec<&str> = global_picks
        .iter()
        .map(|(record, _)| record.key.as_str())
        .collect();
    assert_eq!(
        global_keys,
        vec!["global_visible"],
        "a global source must never evolve links into a project lane"
    );
}

#[test]
fn p4_pick_evolution_neighbors_skips_tombstoned_and_superseded() {
    // Phase 2 #1 tombstone-sync regression. memory_delete soft-deletes
    // via status='tombstoned'; cache cleanup is a fire-and-forget
    // tokio::spawn so a tombstoned/superseded record can linger in
    // `cached` after the SQL row was flipped. This test pins the
    // defensive status filter in pick_evolution_neighbors.
    let new = vec![1.0_f32, 0.0, 0.0];
    let cache = vec![
        mk_cached_with_status("active_kin", "lesson", vec![0.95, 0.31, 0.0], "active"),
        mk_cached_with_status(
            "tombstone_kin",
            "lesson",
            vec![0.92, 0.39, 0.0],
            "tombstoned",
        ),
        mk_cached_with_status(
            "superseded_kin",
            "lesson",
            vec![0.88, 0.47, 0.0],
            "superseded",
        ),
    ];
    let picks = pick_evolution_neighbors(&cache, "probe", &new, 0.65, 5);
    let keys: Vec<&str> = picks.iter().map(|(rec, _)| rec.key.as_str()).collect();

    assert_eq!(keys, vec!["active_kin"], "only active records evolve");
}

#[test]
fn evolution_neighbors_cold_path_selects_and_weights_by_cosine() {
    // Regression: the cold P4-evolve path pulled candidates via
    // memory_search_semantic, which truncates by the importance/recency
    // BLENDED score BEFORE any cosine re-sort — so a high-cosine, low-
    // importance neighbor past the blend cutoff was silently lost from the
    // cold pool while the warm pick_evolution_neighbors (which cosine-ranks
    // every cached row) kept it. The fix pulls by pure cosine
    // (memory_top_k_cosine) and thresholds/excludes here. This helper is the
    // threshold/exclude/cosine-sort stage over that pure-cosine pull.
    let hit = |key: &str, kind: &str, cosine: f32| ab_store::MemoryCosineHit {
        record: b1_mem_with(key, kind, "body"),
        cosine,
    };
    let hits = vec![
        hit("high_cos", "decision", 0.95), // wins by cosine
        hit("probe", "decision", 0.99),    // self → dropped
        hit("a_skill", "skill", 0.98),     // skill → dropped
        hit("mid_cos", "lesson", 0.80),
        hit("low_cos", "decision", 0.70),
        hit("below_thresh", "decision", 0.60), // < 0.65 threshold → dropped
    ];
    let picks = evolution_neighbors_from_cosine_hits(hits, "probe", 0.65, 5);
    let keys: Vec<&str> = picks.iter().map(|(r, _)| r.key.as_str()).collect();
    assert_eq!(
        keys,
        vec!["high_cos", "mid_cos", "low_cos"],
        "self + skill + below-threshold dropped; remainder sorted by COSINE desc"
    );
    // Edge weight is the cosine.
    assert!(
        (picks[0].1 - 0.95).abs() < 1e-6,
        "edge weight must be cosine; got {}",
        picks[0].1
    );
    assert!((picks[2].1 - 0.70).abs() < 1e-6);
    // top_k truncation keeps the highest-cosine neighbor.
    let one = evolution_neighbors_from_cosine_hits(
        vec![hit("a", "decision", 0.9), hit("b", "decision", 0.8)],
        "probe",
        0.65,
        1,
    );
    assert_eq!(one.len(), 1);
    assert_eq!(one[0].0.key, "a");
}

