#[tokio::test]
async fn memory_correction_happy_path_creates_feedback_memory_and_corrects_edge() {
    let (hub, temp_dir) = mk_test_hub_with_store().await;
    let store = hub.store.clone().expect("store");

    // Seed the target memory.
    let target = MemoryRecord {
        key: "tests:target_for_correction".into(),
        kind: "fact".into(),
        content: "the original (about to be corrected) fact".into(),
        tags: vec![],
        related_keys: vec![],
        scope: None,
        created_at: 0,
        updated_at: 0,
        last_accessed_at: 0,
        access_count: 0,
        importance: 0.5,
        status: "active".into(),
        trigger_pattern: None,
        superseded_by: None,
    };
    store.memory_save(&target).await.expect("seed target");

    let tool = MemoryCorrectionTool::new(hub.clone());
    let ctx = ToolContext::default();
    let res = tool
        .execute(
            json!({
                "target_key": "tests:target_for_correction",
                "correction_body": "actually the correction says X holds",
            }),
            &ctx,
        )
        .await
        .expect("execute ok");
    let text = match res.content.first() {
        Some(ab_mcp::ContentBlock::Text { text }) => text.clone(),
        _ => panic!("expected text content"),
    };
    let v: Value = serde_json::from_str(&text).expect("valid json");

    assert_eq!(v["status"], json!("ok"));
    let correction_key = v["correction_key"]
        .as_str()
        .expect("correction_key")
        .to_string();
    assert!(
        correction_key.starts_with("correction:tests:target_for_correction:"),
        "key derived from target + body hash, got {correction_key}"
    );
    assert_eq!(v["target_key"], json!("tests:target_for_correction"));
    assert_eq!(v["edge_type"], json!("corrects"));
    assert!(
        (v["edge_weight"].as_f64().unwrap_or(0.0) - 1.4).abs() < 1e-9,
        "edge_weight should be canonical EDGE_WEIGHT_CORRECTS=1.4"
    );
    assert!(
        (v["importance"].as_f64().unwrap_or(0.0) - 0.7).abs() < 1e-9,
        "default importance 0.7"
    );

    // Verify the feedback memory was created with the right shape.
    let saved = store
        .memory_get(&correction_key)
        .await
        .expect("get correction")
        .expect("correction exists");
    assert_eq!(saved.kind, "feedback");
    assert!(saved.tags.contains(&"correction".to_string()));
    assert!(saved.tags.contains(&"l5".to_string()));
    assert!(saved
        .related_keys
        .contains(&"tests:target_for_correction".to_string()));

    // Verify the edge.
    let edges = store
        .memory_neighbors(&correction_key)
        .await
        .expect("neighbors");
    assert!(
        edges
            .iter()
            .any(|e| e.edge_type == "corrects" && e.to_key == "tests:target_for_correction"),
        "expected corrects edge to target, got {edges:?}"
    );

    let _ = tokio::fs::remove_dir_all(&temp_dir).await;
}

#[tokio::test]
async fn b1_cosurface_inserts_corrector_after_corrected_original() {
    // B1: cosurface_corrections must pull an active corrector in directly
    // after the original it corrects (inbound `corrects` edge), leave other
    // results untouched, never duplicate, and no-op when there is nothing to
    // co-surface. Exercised directly (not via the env-gated search path) so
    // the assertion is deterministic and independent of process env.
    let (hub, temp_dir) = mk_test_hub_with_store().await;
    let store = hub.store.clone().expect("store");

    let original = MemoryRecord {
        key: "b1:original".into(),
        kind: "observation".into(),
        content: "the original possibly-stale claim".into(),
        tags: vec![],
        related_keys: vec![],
        scope: None,
        created_at: 0,
        updated_at: 0,
        last_accessed_at: 0,
        access_count: 0,
        importance: 0.5,
        status: "active".into(),
        trigger_pattern: None,
        superseded_by: None,
    };
    let other = MemoryRecord {
        key: "b1:other".into(),
        content: "an unrelated result".into(),
        ..original.clone()
    };
    let corrector = MemoryRecord {
        key: "correction:b1:original:abc123abc123abc1".into(),
        kind: "feedback".into(),
        content: "actually the corrected claim".into(),
        related_keys: vec!["b1:original".into()],
        ..original.clone()
    };
    store.memory_save(&original).await.expect("save original");
    store.memory_save(&other).await.expect("save other");
    store.memory_save(&corrector).await.expect("save corrector");
    // Inbound corrects edge corrector --corrects--> original. (memory_save's
    // A1 hook also creates this; we link explicitly to keep B1 independent.)
    store
        .memory_link(&corrector.key, &original.key, "corrects", 1.0)
        .await
        .expect("link");

    // A ranked page where the corrected original is a hit.
    let mut hits = vec![
        MemorySearchHit {
            score: 2.0,
            record: original.clone(),
            cosine: None,
        },
        MemorySearchHit {
            score: 1.0,
            record: other.clone(),
            cosine: None,
        },
    ];
    cosurface_corrections(&store, &mut hits, 10, &[]).await;
    let keys: Vec<&str> = hits.iter().map(|h| h.record.key.as_str()).collect();
    assert_eq!(
        keys,
        vec![
            "b1:original",
            "correction:b1:original:abc123abc123abc1",
            "b1:other"
        ],
        "corrector must sit directly after the corrected original"
    );

    // Idempotent: re-running must not insert a second copy.
    cosurface_corrections(&store, &mut hits, 10, &[]).await;
    assert_eq!(
        hits.iter()
            .filter(|h| h.record.key == corrector.key)
            .count(),
        1,
        "no duplicate corrector on re-run"
    );

    // No-op: a page with no corrected original is returned unchanged.
    let mut plain = vec![MemorySearchHit {
        score: 1.0,
        record: other.clone(),
        cosine: None,
    }];
    cosurface_corrections(&store, &mut plain, 10, &[]).await;
    assert_eq!(
        plain.len(),
        1,
        "page without a corrects target is untouched"
    );

    // Output-filter contract: even when the co-surface gate is enabled,
    // excluded kinds must not be reintroduced after the normal search filter.
    let mut exclude_feedback = vec![MemorySearchHit {
        score: 2.0,
        record: original.clone(),
        cosine: None,
    }];
    cosurface_corrections(&store, &mut exclude_feedback, 10, &["feedback".to_string()]).await;
    assert_eq!(
        exclude_feedback
            .iter()
            .map(|h| h.record.key.as_str())
            .collect::<Vec<_>>(),
        vec!["b1:original"],
        "exclude_kinds must still apply to co-surfaced corrections"
    );

    // Gap coverage (review): MULTIPLE correctors on one original — all surface.
    let corr2 = MemoryRecord {
        key: "correction:b1:original:def456def456def4".into(),
        content: "a second, independent correction".into(),
        ..corrector.clone()
    };
    store.memory_save(&corr2).await.expect("save corr2");
    store
        .memory_link(&corr2.key, &original.key, "corrects", 1.0)
        .await
        .expect("link corr2");
    let mut multi = vec![MemorySearchHit {
        score: 2.0,
        record: original.clone(),
        cosine: None,
    }];
    cosurface_corrections(&store, &mut multi, 10, &[]).await;
    let mkeys: std::collections::HashSet<&str> =
        multi.iter().map(|h| h.record.key.as_str()).collect();
    assert!(
        mkeys.contains(corrector.key.as_str()) && mkeys.contains(corr2.key.as_str()),
        "both correctors of one original must surface, got {mkeys:?}"
    );
    assert_eq!(multi[0].record.key, "b1:original", "original stays first");

    // Gap coverage (review): an INACTIVE corrector is skipped even with an edge.
    let mut dead_corr = MemoryRecord {
        key: "correction:b1:original:0000dead0000dead".into(),
        content: "a superseded correction".into(),
        ..corrector.clone()
    };
    dead_corr.status = "superseded".into();
    store.memory_save(&dead_corr).await.expect("save dead corr");
    store
        .memory_link(&dead_corr.key, &original.key, "corrects", 1.0)
        .await
        .expect("link dead corr");
    let mut withdead = vec![MemorySearchHit {
        score: 2.0,
        record: original.clone(),
        cosine: None,
    }];
    cosurface_corrections(&store, &mut withdead, 10, &[]).await;
    assert!(
        withdead.iter().all(|h| h.record.key != dead_corr.key),
        "an inactive corrector must be skipped"
    );

    // Gap coverage (review): a corrector already on the page is not duplicated.
    let mut already = vec![
        MemorySearchHit {
            score: 2.0,
            record: original.clone(),
            cosine: None,
        },
        MemorySearchHit {
            score: 1.5,
            record: corrector.clone(),
            cosine: None,
        },
    ];
    cosurface_corrections(&store, &mut already, 10, &[]).await;
    assert_eq!(
        already
            .iter()
            .filter(|h| h.record.key == corrector.key)
            .count(),
        1,
        "a pre-existing corrector must not be duplicated"
    );

    let _ = tokio::fs::remove_dir_all(&temp_dir).await;
}

fn quota_hit(key: &str, kind: &str, score: f64) -> MemorySearchHit {
    MemorySearchHit {
        score,
        cosine: None,
        record: mk_mem(key, kind, "", &[]),
    }
}

fn no_protected() -> std::collections::HashSet<String> {
    std::collections::HashSet::new()
}

#[test]
fn coactivation_rerank_disable_defaults_to_enabled() {
    // Unset / empty / junk / explicit 0 keep the long-standing rerank ON
    // (disabled == false): the knob is per-deployment, not a default flip.
    assert!(!coactivation_rerank_disabled_from(None));
    assert!(!coactivation_rerank_disabled_from(Some("")));
    assert!(!coactivation_rerank_disabled_from(Some("0")));
    assert!(!coactivation_rerank_disabled_from(Some("no")));
    // Disable switch: same boolean idiom as AGENT_BRIDGE_SEED_BOOST_DISABLE.
    assert!(coactivation_rerank_disabled_from(Some("1")));
    assert!(coactivation_rerank_disabled_from(Some("true")));
    assert!(coactivation_rerank_disabled_from(Some("TRUE")));
}

