async fn ogc_seed_harmful_target(store: &Arc<dyn StateStore>) {
    // A harmful target with quorum-clearing corroboration from 2 sources.
    store
        .memory_save(&t4_memory_record(
            "apply_target",
            "lesson",
            "harmful target body",
            &[],
            &[],
            0,
            0.5,
        ))
        .await
        .expect("seed target");
    for (fb, src) in [("fb1", "agentA"), ("fb2", "agentB")] {
        store
            .memory_save(&t4_memory_record(
                fb,
                "feedback",
                "outcome: harmful",
                &[
                    "retrieval_feedback",
                    "retrieval_feedback:harmful",
                    &format!("retrieval_source:{src}"),
                ],
                &["apply_target"],
                0,
                0.6,
            ))
            .await
            .expect("seed feedback");
    }
}

// Seed a STALE target that consolidates into a higher-ranked same-kind peer,
// exercising the executor's memory_consolidate (edge-first) WRITE branch.
//
// The contents are engineered to clear the planner's similarity gate while
// dodging the store's save-time contradiction auto-supersede — the two use
// DIFFERENT tokenizers: the planner's word bag keeps words of length >= 3
// (memory_consolidate_word_bag) while the store's overlap only keeps tokens of
// length >= 4 (overlap_tokens). So the pair shares many 3-char words (high
// planner jaccard, ~0.8) but each has only a single distinct >= 4-char token
// ("cobra"/"viper") — the store's `new_tokens.len() >= 3` guard isn't even met,
// so neither save supersedes the other and the loser keeps no non-retrieval
// edge (stays shadow-eligible). The winner outranks the loser via importance
// (rank = importance*(1+access_count)): 0.7 > 0.3.
async fn ogc_seed_consolidate_pair(store: &Arc<dyn StateStore>) {
    // Loser (the stale target) — saved first.
    store
        .memory_save(&t4_memory_record(
            "merge_loser",
            "lesson",
            "red box sun the cat dog hen pig owl cobra",
            &[],
            &[],
            0,
            0.3,
        ))
        .await
        .expect("seed loser");
    // Winner (higher-ranked similar peer) — shares all 3-char words, differs
    // only in the single >= 4-char token, so the store does not auto-supersede.
    store
        .memory_save(&t4_memory_record(
            "merge_winner",
            "lesson",
            "red box sun the cat dog hen pig owl viper",
            &[],
            &[],
            0,
            0.7,
        ))
        .await
        .expect("seed winner");
    // Two distinct-source stale feedbacks on the loser → quorum met, eligible.
    for (fb, src) in [("fbs1", "memory_search"), ("fbs2", "memory_get")] {
        store
            .memory_save(&t4_memory_record(
                fb,
                "feedback",
                "outcome: stale",
                &[
                    "retrieval_feedback",
                    "retrieval_feedback:stale",
                    &format!("retrieval_source:{src}"),
                ],
                &["merge_loser"],
                0,
                0.6,
            ))
            .await
            .expect("seed stale feedback");
    }
}

#[tokio::test]
async fn outcome_gated_apply_trial_tool_default_off_blocks_and_mutates_nothing() {
    let _lock = frontend_env_test_setup();
    let prior_enable = std::env::var(OUTCOME_GATED_CONSOLIDATION_ENABLE_ENV).ok();
    let prior_disable = std::env::var(OUTCOME_GATED_CONSOLIDATION_DISABLE_ENV).ok();
    std::env::remove_var(OUTCOME_GATED_CONSOLIDATION_ENABLE_ENV);
    std::env::remove_var(OUTCOME_GATED_CONSOLIDATION_DISABLE_ENV);

    let (hub, temp_dir) = mk_test_hub_with_store().await;
    let store = hub.store.clone().expect("store");
    ogc_seed_harmful_target(&store).await;

    let tool = OutcomeGatedConsolidationApplyTrialTool::new(hub.clone());
    let out = tool
        .execute(
            json!({
                "transition_gate_packet": ogc_allowed_transition_packet(),
                "per_call_opt_in": true,
                "max_records": 50
            }),
            &ToolContext::default(),
        )
        .await
        .expect("execute");
    let trial = result_text_as_json(&out);
    // Feature env is OFF ⇒ no plan even with an allowed packet + opt-in.
    assert_eq!(trial["status"], json!("blocked_by_runtime_gate"));
    assert!(trial["plan"].as_array().unwrap().is_empty());
    let after = store
        .memory_get("apply_target")
        .await
        .expect("lookup")
        .expect("still present");
    assert_eq!(after.status, "active");
    ogc_assert_trial_no_side_effects(&trial);

    restore_env_var(OUTCOME_GATED_CONSOLIDATION_ENABLE_ENV, prior_enable);
    restore_env_var(OUTCOME_GATED_CONSOLIDATION_DISABLE_ENV, prior_disable);
    let _ = tokio::fs::remove_dir_all(&temp_dir).await;
}

#[tokio::test]
async fn outcome_gated_apply_trial_tool_enabled_plans_but_mutates_nothing() {
    let _lock = frontend_env_test_setup();
    let prior_enable = std::env::var(OUTCOME_GATED_CONSOLIDATION_ENABLE_ENV).ok();
    let prior_disable = std::env::var(OUTCOME_GATED_CONSOLIDATION_DISABLE_ENV).ok();
    std::env::set_var(OUTCOME_GATED_CONSOLIDATION_ENABLE_ENV, "1");
    std::env::remove_var(OUTCOME_GATED_CONSOLIDATION_DISABLE_ENV);

    let (hub, temp_dir) = mk_test_hub_with_store().await;
    let store = hub.store.clone().expect("store");
    ogc_seed_harmful_target(&store).await;

    let tool = OutcomeGatedConsolidationApplyTrialTool::new(hub.clone());
    let out = tool
        .execute(
            json!({
                "transition_gate_packet": ogc_allowed_transition_packet(),
                "per_call_opt_in": true,
                "max_records": 50
            }),
            &ToolContext::default(),
        )
        .await
        .expect("execute");
    let trial = result_text_as_json(&out);
    assert_eq!(trial["status"], json!("trial_complete"));
    let entry = ogc_trial_entry(&trial, "apply_target");
    assert_eq!(entry["decision"], json!("accepted"));
    assert_eq!(entry["planned_mutation"]["op"], json!("archive_status"));
    assert_eq!(entry["planned_mutation"]["to_status"], json!("archived"));

    // The trial planned an archive but must NOT have applied it.
    let after = store
        .memory_get("apply_target")
        .await
        .expect("lookup")
        .expect("still present");
    assert_eq!(after.status, "active", "dry-run trial must not archive");
    ogc_assert_trial_no_side_effects(&trial);

    restore_env_var(OUTCOME_GATED_CONSOLIDATION_ENABLE_ENV, prior_enable);
    restore_env_var(OUTCOME_GATED_CONSOLIDATION_DISABLE_ENV, prior_disable);
    let _ = tokio::fs::remove_dir_all(&temp_dir).await;
}

