/// Regression for #1758 — the bug that bit this very session: an
/// opus-4.8 @ 1M session read 247% "saturated/urgent" because the limit
/// defaulted to 200K. With an explicit `context_window=1_000_000` the
/// same 30-turn load (15k + 30*4k = 135k = 13.5%) reads "fresh", and the
/// 1M-beta hint is suppressed (caller already supplied the truth).
#[tokio::test]
async fn context_pressure_estimate_explicit_window_fixes_1m_inflation() {
    let tool = ContextPressureEstimateTool::new();
    let ctx = ToolContext::default();
    let res = tool
        .execute(
            json!({
                "model": "claude-opus-4-8",
                "conversation_turns": 30,
                "context_window": 1_000_000
            }),
            &ctx,
        )
        .await
        .expect("execute ok");
    let text = match res.content.first() {
        Some(ab_mcp::ContentBlock::Text { text }) => text.clone(),
        _ => panic!("expected text content"),
    };
    let v: Value = serde_json::from_str(&text).expect("valid json");
    assert_eq!(v["model_limit"], json!(1_000_000));
    assert_eq!(v["model_limit_source"], json!("explicit"));
    assert_eq!(v["fatigue_tier"], json!("fresh"));
    assert_eq!(v["long_context_beta_possible"], json!(false));
    // Same load WITHOUT the override would be 67.5% (strained) on 200K —
    // prove the override actually moved the needle.
    let res_default = tool
        .execute(
            json!({"model": "claude-opus-4-8", "conversation_turns": 30}),
            &ctx,
        )
        .await
        .expect("execute ok");
    let td = match res_default.content.first() {
        Some(ab_mcp::ContentBlock::Text { text }) => text.clone(),
        _ => panic!("expected text content"),
    };
    let vd: Value = serde_json::from_str(&td).expect("valid json");
    assert_eq!(vd["model_limit"], json!(200_000));
    assert_eq!(vd["fatigue_tier"], json!("strained"));
}

/// On a 1M-beta family with NO explicit window, the tool keeps the
/// conservative 200K default but flags `long_context_beta_possible` so
/// the caller knows to pass `context_window`. A non-beta model is not
/// flagged.
#[tokio::test]
async fn context_pressure_estimate_flags_1m_beta_when_no_window() {
    let tool = ContextPressureEstimateTool::new();
    let ctx = ToolContext::default();

    let res = tool
        .execute(json!({"model": "claude-opus-4-8"}), &ctx)
        .await
        .expect("execute ok");
    let text = match res.content.first() {
        Some(ab_mcp::ContentBlock::Text { text }) => text.clone(),
        _ => panic!("expected text content"),
    };
    let v: Value = serde_json::from_str(&text).expect("valid json");
    assert_eq!(v["model_limit"], json!(200_000));
    assert_eq!(v["model_limit_source"], json!("model_default"));
    assert_eq!(v["long_context_beta_possible"], json!(true));
    assert!(
        v["note"].as_str().unwrap().contains("1M beta"),
        "note must carry the 1M-beta caveat"
    );

    // Non-beta family (sonnet-3.5): default limit, NOT flagged.
    let res2 = tool
        .execute(json!({"model": "claude-3-5-sonnet-20241022"}), &ctx)
        .await
        .expect("execute ok");
    let t2 = match res2.content.first() {
        Some(ab_mcp::ContentBlock::Text { text }) => text.clone(),
        _ => panic!("expected text content"),
    };
    let v2: Value = serde_json::from_str(&t2).expect("valid json");
    assert_eq!(v2["long_context_beta_possible"], json!(false));
}

// ── L6 P2 — tool_call_attention_report (pure aggregator) ──────────

fn mk_call(ts: i64, name: &str, ok: bool, result_size: u32) -> ab_store::McpToolCallRow {
    ab_store::McpToolCallRow {
        id: ts,
        ts,
        tool_name: name.into(),
        mcp_session_id: Some("test-session".into()),
        duration_ms: 10,
        ok,
        args_size: Some(100),
        result_size: Some(result_size),
    }
}

#[test]
fn attention_report_empty_input_returns_zero_metrics() {
    let r = compute_attention_report(&[], 7200, 2500, 600);
    assert_eq!(r.total_calls, 0);
    assert_eq!(r.high_yield_calls, 0);
    assert_eq!(r.followed_up_calls, 0);
    assert_eq!(r.ignored_calls, 0);
    assert!(r.followed_up_ratio.abs() < 1e-9);
    assert!(r.ignored.is_empty());
    assert!(r.top_yield.is_empty());
}

#[test]
fn attention_report_filters_failed_calls_from_high_yield() {
    // Two calls: one ok+big, one failed+big. Only ok one counts as
    // high-yield. Failed call ALSO counts as a follow-up signal for
    // the first call (≠self).
    let calls = vec![
        mk_call(1000, "browser_extract_text", true, 50_000),
        mk_call(1100, "browser_extract_text", false, 50_000),
    ];
    let r = compute_attention_report(&calls, 7200, 2500, 600);
    assert_eq!(
        r.high_yield_calls, 1,
        "failed call must not enter high-yield"
    );
    assert_eq!(r.followed_up_calls, 1);
    assert_eq!(r.ignored_calls, 0);
}

#[test]
fn attention_report_marks_ignored_when_no_followup_within_window() {
    // Call at t=0 with big result; next call at t=10000 (far past
    // 600s window) → ignored.
    let calls = vec![
        mk_call(0, "memory_search", true, 50_000),
        mk_call(10_000, "browser_navigate", true, 500),
    ];
    let r = compute_attention_report(&calls, 7200, 2500, 600);
    assert_eq!(r.high_yield_calls, 1);
    assert_eq!(r.ignored_calls, 1);
    assert_eq!(r.ignored[0].tool_name, "memory_search");
    assert_eq!(r.ignored[0].result_size, 50_000);
}

#[test]
fn attention_report_followed_up_when_any_call_in_window() {
    // High-yield at t=0; small follow-up at t=120 (well within 600s).
    let calls = vec![
        mk_call(0, "memory_search", true, 50_000),
        mk_call(120, "memory_get", true, 200),
    ];
    let r = compute_attention_report(&calls, 7200, 2500, 600);
    assert_eq!(r.high_yield_calls, 1);
    assert_eq!(r.followed_up_calls, 1);
    assert_eq!(r.ignored_calls, 0);
    assert!((r.followed_up_ratio - 1.0).abs() < 1e-9);
    assert!(r.ignored.is_empty());
}

#[test]
fn attention_report_top_yield_sorted_by_size_desc() {
    // Mix small + huge + medium high-yield calls; verify top_yield
    // is sorted desc by result_size.
    let calls = vec![
        mk_call(0, "small_tool", true, 100), // below threshold
        mk_call(10, "huge_tool", true, 100_000),
        mk_call(20, "medium_tool", true, 5_000),
        mk_call(30, "follow_up", true, 50), // within 600s of all
    ];
    let r = compute_attention_report(&calls, 7200, 2500, 600);
    assert_eq!(
        r.high_yield_calls, 2,
        "huge + medium qualify, small below threshold"
    );
    // huge_tool > medium_tool by size.
    assert_eq!(r.top_yield[0].tool_name, "huge_tool");
    assert_eq!(r.top_yield[1].tool_name, "medium_tool");
    // Both should be marked followed_up (the small + follow_up calls are within 600s).
    assert!(r.top_yield.iter().all(|c| c.followed_up));
}

#[test]
fn attention_report_handles_missing_result_size() {
    // result_size=None → not high-yield (heuristic: unknown size
    // is conservative no-signal).
    let calls = vec![ab_store::McpToolCallRow {
        id: 0,
        ts: 0,
        tool_name: "weird_tool".into(),
        mcp_session_id: Some("test-session".into()),
        duration_ms: 10,
        ok: true,
        args_size: Some(100),
        result_size: None,
    }];
    let r = compute_attention_report(&calls, 7200, 2500, 600);
    assert_eq!(r.high_yield_calls, 0);
}

#[test]
fn practical_scorecard_reports_continuation_completion_and_recovery_proxies() {
    let calls = vec![
        mk_call(100, "session_bootstrap", true, 2_000),
        mk_call(112, "memory_get", true, 500),
        mk_call(200, "memory_save", false, 100),
        mk_call(205, "memory_save", false, 100),
        mk_call(215, "memory_save", true, 500),
        mk_call(300, "plan_update", true, 500),
        mk_call(400, "session_finalize", true, 500),
    ];
    let report = compute_practical_workflow_scorecard(&calls, 86_400, 600, 1_000);

    assert_eq!(report.total_calls, 7);
    assert_eq!(report.successful_calls, 5);
    assert_eq!(report.failed_calls, 2);
    assert_eq!(report.continuation.bootstrap_calls, 1);
    assert_eq!(report.continuation.attributed_bootstrap_calls, 1);
    assert_eq!(report.continuation.legacy_unattributed_bootstraps, 0);
    assert_eq!(report.continuation.eligible_bootstrap_calls, 1);
    assert_eq!(report.continuation.right_censored_bootstraps, 0);
    assert_eq!(report.continuation.bootstraps_with_followup, 1);
    assert_eq!(report.continuation.eligible_bootstraps_without_followup, 0);
    assert_eq!(report.continuation.followup_rate, Some(1.0));
    assert_eq!(report.continuation.median_followup_secs, Some(12));
    assert_eq!(report.completion.finalize_signals, 1);
    assert_eq!(report.completion.plan_update_signals, 1);
    assert_eq!(report.recovery.failures_followed_by_success, 2);
    assert_eq!(report.recovery.repeated_failure_loops, 1);
    assert_eq!(report.coordination.calls, 3);
    assert_eq!(report.coordination.memory_saves, 3);
    assert_eq!(report.coordination.ratio, Some(3.0 / 7.0));
    assert!(!report
        .recommendations
        .iter()
        .any(|item| item.contains("More than half")));
    assert_eq!(report.operator_burden.instrumentation_status, "unavailable");
    assert_eq!(report.operator_burden.repeated_authorization_prompts, None);
    assert_eq!(report.operator_burden.manual_interventions, None);
}

#[test]
fn practical_scorecard_flags_coordination_majority() {
    let mut calls = Vec::new();
    for ts in 0..6 {
        calls.push(mk_call(ts, "forum_read", true, 500));
    }
    for ts in 6..11 {
        calls.push(mk_call(ts, "forum_post", true, 200));
    }
    for ts in 11..15 {
        calls.push(mk_call(ts, "memory_save", true, 300));
    }
    for ts in 15..18 {
        calls.push(mk_call(ts, "capabilities", true, 500));
    }
    for ts in 18..20 {
        calls.push(mk_call(ts, "memory_get", true, 500));
    }

    let report = compute_practical_workflow_scorecard(&calls, 3_600, 600, 1_000);

    assert_eq!(report.schema_version, 3);
    assert_eq!(report.coordination.calls, 18);
    assert_eq!(report.coordination.ratio, Some(0.9));
    assert_eq!(report.coordination.forum_reads, 6);
    assert_eq!(report.coordination.forum_posts, 5);
    assert_eq!(report.coordination.memory_saves, 4);
    assert_eq!(report.coordination.capability_checks, 3);
    assert!(report
        .recommendations
        .iter()
        .any(|item| item.contains("More than half")));
}

