    let store = hub.store.clone().expect("store");
    let long_content = "FTS5 column-scoped parser warning ".repeat(96);

    store
        .memory_save(&b3_mem("decision_prior_long", "decision", &long_content))
        .await
        .expect("save prior");

    let tool = MemorySaveTool::new(hub);
