/// Regression: `MemorySearchHit.cosine` is the raw geometric distance;
/// `.score` is post-blend (cosine + importance/recency bonuses, can
/// exceed 1.0). Asserts the invariant `score ≥ cosine` when cosine is
/// present — this is what makes the two fields distinguishable.
#[tokio::test(flavor = "current_thread")]
async fn memory_search_semantic_cosine_bounded_and_below_blended_score() {
    let store = b3_test_store().await;
    let mut rec = b3_mem(
        "lesson_anchor",
        "lesson",
        "anchor content for cosine bound test",
    );
    rec.importance = 0.9; // make blend bonus prominent
    store.memory_save(&rec).await.expect("save");

    let hits = store
        .memory_search_semantic("anchor content for cosine bound test", 5, 0.0)
        .await
        .expect("semantic");
    assert!(!hits.is_empty(), "expected ≥1 semantic hit");
    for hit in &hits {
        let cos = hit.cosine.expect("semantic path must populate cosine") as f64;
        assert!(
            (-1.0..=1.0).contains(&cos),
            "cosine must be in [-1, 1], got {}",
            cos
        );
        assert!(
            hit.score >= cos - 1e-6,
            "score (blended) must be ≥ cosine (got score={}, cosine={})",
            hit.score,
            cos
        );
    }
}

#[tokio::test(flavor = "current_thread")]
async fn memory_search_semantic_warm_cache_matches_sql_blend() {
    // Regression: mode=semantic had TWO scorers. The SQL path
    // (memory_search_semantic) used the owner-approved semantic_rank_weights
    // blend; the warm embed-cache path hardcoded `cosine + 0.2·importance`,
    // bypassing the weights + every AGENT_BRIDGE_SEMANTIC_* env knob — so
    // ranking silently diverged by cache state. Both now route through the
    // shared semantic_blend_score; assert the warm-cache tool path reproduces
    // the SQL path's scores. The varied importance/kind corpus below makes the
    // OLD 0.2·importance formula disagree, so this fails on the pre-fix code.
    let (hub, temp_dir) = mk_test_hub_with_store().await;
    let store = hub.store.clone().expect("store");

    let now = ab_store::now_secs();
    let mk = |key: &str, kind: &str, suffix: &str, importance: f64, age_days: i64, access: u64| {
        ab_store::MemoryRecord {
            key: key.into(),
            kind: kind.into(),
            content: format!("shared semantic anchor tokens alpha bravo charlie {suffix}"),
            tags: vec![],
            related_keys: vec![],
            scope: None,
            created_at: now - age_days * 86_400,
            updated_at: now - age_days * 86_400,
            last_accessed_at: now - age_days * 86_400,
            access_count: access,
            importance,
            status: "active".into(),
            trigger_pattern: None,
            superseded_by: None,
        }
    };
    // Shared anchor tokens (real cosine to the query) + unique suffix per row
    // (escape memory_save's overlap-supersede). Distinct importance/kind/
    // recency so the conservative blend and the old 0.2·importance formula
    // rank differently.
    let corpus = [
        mk("warm_fresh_decision", "decision", "delta", 0.30, 0, 0),
        mk("warm_stale_feedback", "feedback", "echo", 0.90, 45, 12),
        mk("warm_mid_lesson", "lesson", "foxtrot", 0.60, 10, 3),
    ];
    for rec in &corpus {
        store.memory_save(rec).await.expect("save");
    }

    let query = "shared semantic anchor tokens alpha bravo charlie";

    // SQL (cold) path — raw blend scores, no cache involved.
    let sql_hits = store
        .memory_search_semantic(query, 10, 0.0)
        .await
        .expect("sql semantic");
    assert!(
        sql_hits.len() >= 3,
        "expected all 3 rows from sql path, got {}",
        sql_hits.len()
    );
    let sql_scores: std::collections::HashMap<String, f64> = sql_hits
        .iter()
        .map(|h| (h.record.key.clone(), h.score))
        .collect();

    // Populate the warm embed cache from the SAME store snapshot (identical
    // embeddings ⇒ identical cosine ⇒ any score delta is formula-only).
    let rows = store
        .memory_load_embeddings()
        .await
        .expect("load embeddings");
    *hub.memory_embed_cache.lock().await = Some(rows);

    // Warm path through the tool (hits the embed-cache branch).
    let tool = MemorySearchTool::new(hub.clone());
    let res = tool
        .execute(
            json!({"query": query, "mode": "semantic", "limit": 10, "threshold": 0.0}),
            &ToolContext::default(),
        )
        .await
        .expect("warm semantic");
    let warm = result_text_as_json(&res);
    let warm_arr = warm.as_array().expect("array result");
    assert_eq!(
        warm_arr.len(),
        sql_hits.len(),
        "warm and sql must surface the same rows"
    );

    let mut warm_order: Vec<String> = Vec::new();
    for hit in warm_arr {
        let key = hit["record"]["key"]
            .as_str()
            .expect("record.key")
            .to_string();
        let warm_score = hit["score"].as_f64().expect("score");
        let sql_score = *sql_scores
            .get(&key)
            .unwrap_or_else(|| panic!("key {key} missing from sql path"));
        assert!(
            (warm_score - sql_score).abs() < 1e-4,
            "warm score {warm_score} must equal sql blend {sql_score} for {key}"
        );
        warm_order.push(key);
    }

    // Identical scores ⇒ identical sorted order.
    let sql_order: Vec<String> = sql_hits.iter().map(|h| h.record.key.clone()).collect();
    assert_eq!(
        warm_order, sql_order,
        "warm-cache order must equal SQL order"
    );

    let _ = tokio::fs::remove_dir_all(&temp_dir).await;
}

#[tokio::test]
async fn memory_search_semantic_warm_cache_reflects_post_prime_db_mutations() {
    // Regression: the warm embed cache is a FROZEN snapshot. Mutations that
    // change importance/status WITHOUT touching it — valence-importance
    // apply, decay, reinforce, correction, archive — used to be invisible on
    // the warm path: it leaked rows that left status='active' after priming
    // AND scored with the stale frozen importance, so the arc6 valence boost
    // never reached warm-daemon ranking. The live-meta overlay re-hydrates
    // importance + drops now-inactive rows, so warm matches a FRESH SQL
    // search taken AFTER the mutation. This fails on the pre-overlay code
    // (warm_gone would still surface; warm_bump would score at 0.20).
    let (hub, temp_dir) = mk_test_hub_with_store().await;
    let store = hub.store.clone().expect("store");

    let now = ab_store::now_secs();
    // Distinct kinds per row: memory_save's contradiction-supersede only
    // fires within the SAME (kind, scope), and the shared anchor tokens push
    // token-overlap > 0.5 — so same-kind rows would collapse into one active
    // row before we could mutate them. Distinct kinds keep all three alive
    // (same escape the sibling parity test uses).
    let mk = |key: &str, kind: &str, suffix: &str, importance: f64| ab_store::MemoryRecord {
        key: key.into(),
        kind: kind.into(),
        content: format!("shared semantic anchor tokens alpha bravo charlie {suffix}"),
        tags: vec![],
        related_keys: vec![],
        scope: None,
        created_at: now,
        updated_at: now,
        last_accessed_at: now,
        access_count: 3,
        importance,
        status: "active".into(),
        trigger_pattern: None,
        superseded_by: None,
    };
    let corpus = [
        mk("warm_bump", "decision", "delta", 0.20), // importance bumped post-prime
        mk("warm_gone", "lesson", "echo", 0.50),    // leaves status='active' post-prime
        mk("warm_stable", "fact", "foxtrot", 0.40), // untouched control
    ];
    for rec in &corpus {
        store.memory_save(rec).await.expect("save");
    }

    // Prime the warm cache with the ORIGINAL snapshot — importance
    // 0.20/0.50/0.40, all active. This is the frozen state a long-running
    // daemon holds.
    let snapshot = store
        .memory_load_embeddings()
        .await
        .expect("load embeddings");
    *hub.memory_embed_cache.lock().await = Some(snapshot);

    // Mutate the DB AFTER priming — the cache does NOT observe these.
    assert!(store
        .memory_set_importance("warm_bump", 0.95)
        .await
        .expect("bump importance"));
    // Soft-delete stands in for any active→non-active transition (supersede/
    // archive/delete). Call the STORE directly so the tool's cache-eviction
    // spawn never fires — the frozen cache keeps warm_gone as "active",
    // exactly reproducing the leak a real daemon would hit.
    assert!(store.memory_delete("warm_gone").await.expect("delete"));

    let query = "shared semantic anchor tokens alpha bravo charlie";

    // Fresh SQL search = ground truth (reflects both mutations).
    let sql_hits = store
        .memory_search_semantic(query, 10, 0.0)
        .await
        .expect("sql semantic");
    let sql_scores: std::collections::HashMap<String, f64> = sql_hits
        .iter()
        .map(|h| (h.record.key.clone(), h.score))
        .collect();
    assert!(
        !sql_scores.contains_key("warm_gone"),
        "sql ground truth must exclude the deleted row"
    );

    // Warm path through the tool.
    let tool = MemorySearchTool::new(hub.clone());
    let res = tool
        .execute(
            json!({"query": query, "mode": "semantic", "limit": 10, "threshold": 0.0}),
            &ToolContext::default(),
        )
        .await
        .expect("warm semantic");
    let warm = result_text_as_json(&res);
    let warm_arr = warm.as_array().expect("array result");
    let warm_keys: Vec<String> = warm_arr
        .iter()
        .map(|h| h["record"]["key"].as_str().expect("key").to_string())
        .collect();

    // (1) The row that left status='active' after priming is DROPPED on warm,
    //     even though the frozen cache still holds it as active.
    assert!(
        !warm_keys.contains(&"warm_gone".to_string()),
        "warm must drop the row deleted after priming; got {warm_keys:?}"
    );
    assert_eq!(
        warm_keys.len(),
        2,
        "only the 2 still-active rows remain, got {warm_keys:?}"
    );

    // (2) Warm scores now equal the FRESH SQL blend (fresh importance, not
    //     the frozen 0.20/0.40).
    for hit in warm_arr {
        let key = hit["record"]["key"].as_str().expect("key").to_string();
        let warm_score = hit["score"].as_f64().expect("score");
        let sql_score = *sql_scores
            .get(&key)
            .unwrap_or_else(|| panic!("key {key} missing from fresh sql path"));
        assert!(
            (warm_score - sql_score).abs() < 1e-4,
            "warm score {warm_score} must equal fresh sql blend {sql_score} for {key}"
        );
    }

    // (3) The bumped row's returned record exposes the FRESH importance,
    //     so downstream consumers see 0.95, not the frozen 0.20.
    let bump_hit = warm_arr
        .iter()
        .find(|h| h["record"]["key"] == "warm_bump")
        .expect("warm_bump present");
    let bump_imp = bump_hit["record"]["importance"]
        .as_f64()
        .expect("record.importance");
    assert!(
        (bump_imp - 0.95).abs() < 1e-6,
        "warm record must expose fresh importance 0.95, got {bump_imp}"
    );

    let _ = tokio::fs::remove_dir_all(&temp_dir).await;
}

// ── B1 project-state digest — formatter (audit-gap B1 v0) ────────────────

fn b1_mem_with(key: &str, kind: &str, content: &str) -> ab_store::MemoryRecord {
    ab_store::MemoryRecord {
        key: key.to_string(),
        kind: kind.to_string(),
        content: content.to_string(),
        tags: vec![],
        related_keys: vec![],
        scope: None,
        created_at: 0,
        updated_at: 0,
        last_accessed_at: 0,
        access_count: 0,
        importance: 0.7,
        status: "active".to_string(),
        trigger_pattern: None,
        superseded_by: None,
    }
}

#[test]
fn b1_digest_block_returns_none_when_all_buckets_empty() {
    assert!(
        super::format_project_state_digest_block(&[], &[], &[], false, 120).is_none(),
        "empty buckets → no block emitted (avoid visual noise on fresh store)"
    );
}

#[test]
fn b1_digest_block_compact_header_matches_total_count() {
    let dec = vec![b1_mem_with("dec_a", "decision", "decision body A")];
    let hnd = vec![b1_mem_with(
        "handoff_z",
        "session_handoff",
        "handoff body Z",
    )];
    let prj = vec![
        b1_mem_with("prj_a", "project", "project body A"),
        b1_mem_with("prj_b", "project", "project body B"),
    ];
    let block = super::format_project_state_digest_block(&dec, &hnd, &prj, true, 80)
        .expect("non-empty buckets → block emitted");
    let header = &block[0];
    assert!(
        header.contains("4"),
        "compact header must include total count (got {:?})",
        header
    );
    assert!(
        header.contains("digest"),
        "compact header must include 'digest' (got {:?})",
        header
    );
}

#[test]
fn b1_digest_block_full_header_lists_bucket_sizes() {
    let dec = vec![
        b1_mem_with("dec_a", "decision", "A"),
        b1_mem_with("dec_b", "decision", "B"),
    ];
    let hnd: Vec<ab_store::MemoryRecord> = vec![];
    let prj = vec![b1_mem_with("prj_a", "project", "P")];
    let block = super::format_project_state_digest_block(&dec, &hnd, &prj, false, 120)
        .expect("non-empty buckets → block emitted");
    let header = &block[0];
    assert!(
        header.contains("2D") && header.contains("0H") && header.contains("1P"),
        "full header must list 2D + 0H + 1P breakdown (got {:?})",
        header
    );
}

#[test]
fn b1_digest_block_skips_empty_subsections_in_body() {
    let dec = vec![b1_mem_with("dec_solo", "decision", "only decision")];
    let block = super::format_project_state_digest_block(&dec, &[], &[], false, 120)
        .expect("decisions only → block emitted");
    let joined = block.join("\n");
    assert!(
        joined.contains("dec_solo"),
        "decision row must appear (got {:?})",
        joined
    );
    assert!(
        !joined.contains("-- last handoff --"),
        "empty handoff bucket must NOT emit subsection label (got {:?})",
        joined
    );
    assert!(
        !joined.contains("-- recently touched projects --"),
        "empty project bucket must NOT emit subsection label"
    );
}

// ---- S4 compact search projection (s4_compact_search_projection_gate_20260709) ----

fn s4_hit(content: &str, cosine: Option<f32>) -> ab_store::MemorySearchHit {
    let mut rec = b1_mem_with("s4_key", "decision", content);
    rec.tags = vec!["ab-improvement".to_string(), "gated".to_string()];
    ab_store::MemorySearchHit {
        record: rec,
        score: 1.23,
        cosine,
    }
}

#[test]
fn s4_compact_projection_has_exactly_the_cue_tag_fields_and_no_body() {
    let long: String = "记".repeat(500);
    let v = super::memory_search_hit_value_compact(&s4_hit(&long, Some(0.87)));
    let obj = v.as_object().expect("compact hit is an object");
    let mut keys: Vec<&str> = obj.keys().map(|s| s.as_str()).collect();
    keys.sort_unstable();
    assert_eq!(
        keys,
        vec![
            "content_chars",
            "content_preview",
            "content_truncated",
            "cosine",
            "importance",
            "key",
            "kind",
            "score",
            "tags",
        ],
        "compact projection must expose the cue/tag layer and NOTHING else \
         (no `record`, no full `content`, no continuity blob)"
    );
    assert_eq!(obj["key"], "s4_key");
    assert_eq!(obj["kind"], "decision");
    assert_eq!(obj["score"], 1.23);
    assert_eq!(obj["content_chars"], 500);
    assert_eq!(obj["content_truncated"], true);
}

#[test]
fn s4_compact_preview_truncates_by_chars_not_bytes() {
    // 500 CJK chars = 1500 UTF-8 bytes; a byte-based slice at 200 would land
    // mid-code-point and panic. Char-based take(200) must yield exactly 200
    // chars and valid UTF-8.
    let long: String = "忆".repeat(500);
    let v = super::memory_search_hit_value_compact(&s4_hit(&long, None));
    let preview = v["content_preview"].as_str().expect("preview is a string");
    assert_eq!(preview.chars().count(), 200);
    assert!(preview.chars().all(|c| c == '忆'));
}

#[test]
fn s4_compact_short_content_is_whole_and_unflagged() {
    let v = super::memory_search_hit_value_compact(&s4_hit("short body", None));
    assert_eq!(v["content_preview"], "short body");
    assert_eq!(v["content_chars"], 10);
    assert_eq!(v["content_truncated"], false);
    assert!(
        v.get("cosine").is_none(),
        "fts-path hits (cosine=None) must omit the cosine field, matching \
         the full projection's skip_serializing_if contract"
    );
}

#[test]
fn s4_default_full_projection_still_carries_record_and_content() {
    // The byte-identical-default contract: the pre-existing full path keeps
    // its shape (hit envelope + full `record` with `content`) — compact is
    // strictly opt-in and must not have touched it.
    let v = super::memory_search_hit_value_with_continuity(&s4_hit("full body here", Some(0.5)));
    let rec = v.get("record").expect("full hit keeps `record`");
    assert_eq!(rec["content"], "full body here");
    assert_eq!(rec["key"], "s4_key");
    assert!(v.get("content_preview").is_none());
}
